'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('short-term','Short-term combines short and term; it describes something lasting or needed for only a brief period.',C('short-term.s1','金融','The family took out a short-term loan to cover expenses until the new job began.','这家人办理了一笔短期贷款，以支付新工作开始前的开销。','a short-term loan/contract/solution','形容词，指只持续或只需要很短一段时间。','loan covers brief interval.','金融'),M('They chose a short-term contract that would continue unchanged for twenty years.','They chose a short-term contract that would end after three months.','持续二十年不符合“短期”的意思。','meaning'),[Q(1,'A short-term loan is expected to…','last for a brief period','remain unpaid for a century','replace every long-term plan','Short-term means lasting only a short time.','meaning'),Q(1,'Why might a family need a short-term loan?','To bridge a brief gap before the next income arrives.','To fund an expense that will never be repaid.','To describe a permanent shortage of water.','The example uses the loan for a temporary gap.','context'),Q(1,'Which phrase is natural?','a short-term contract','a shortly-term contract','a short-termly contract','Short-term is the compound adjective before contract.','grammar'),Q(1,'Which is the opposite time frame of short-term?','long-term','shortage','shorthand','Long-term refers to a long period.','meaning')]);
P('shortage','Shortage is formed from short + -age, a suffix used in nouns for a condition or amount; it means supply is below demand, or the unmet part of a needed total.',[C('shortage.s1','公共事务','A shortage of clean water forced the town to limit household use.','清洁水短缺迫使小镇限制家庭用水。','a shortage of + resource; face a shortage','名词，指供应不能满足需求的状态。','demand exceeds supply.','公共事务'),C('shortage.s2','财务','The project closed with a budget shortage of two thousand dollars.','项目结束时预算还差两千美元。','a shortage of + amount; a shortage of $X','也可指所需总量中尚未提供的部分。','unfunded amount specified.','财务'),C('shortage.s3','民生','After the drought, several villages faced a serious shortage of grain.','旱灾之后，几个村庄面临严重粮食短缺。','a shortage of food/basic goods','还可表示某地粮食或其他必需品严重不足。','basic food scarce.','民生')],M('The warehouse reported a shortage of 500 masks even though it had 800 masks and needed only 300.','The warehouse reported a shortage of 500 masks because it had only 300 but needed 800.','现有数量超过需求，不会短缺500件。','meaning'),[Q(1,'A shortage of water means…','the available supply does not meet demand','there is more water than anyone needs','water has been turned into a solid','Shortage sense 1 is insufficient supply.','meaning'),Q(2,'A shortage of $2,000 is…','the amount still missing from the required total','the full amount already paid','a kind of short-term loan','Sense 2 names the unprovided part of a total.','meaning'),Q(3,'A serious shortage of grain after drought concerns…','a lack of a basic good in a place','an excess of grain in every village','a short written note','The third sense describes severe scarcity of necessities.','context'),Q(1,'Which phrase is standard?','a shortage of medical supplies','a shortage for medical supplies of','a shortness medical supplyage','Of introduces the item in short supply.','grammar')]);
P('shortcoming','Shortcoming combines short with coming in the sense of falling short of a standard; it names a way in which someone or something is not good enough.',C('shortcoming.s1','评价','The review praised the design but noted one shortcoming: it was difficult to repair.','评审称赞了设计，但指出一个缺点：它很难维修。','a shortcoming of/in + person/plan; address a shortcoming','名词，指人或事物不够好的一个方面。','specific flaw limits design.','评价'),M('The report listed the plan’s shortcoming as its most successful and reliable feature.','The report listed the plan’s shortcoming as its least reliable feature.','优点不能同时被当作缺点。','distinction'),[Q(1,'A shortcoming in a design is…','a feature that makes it less than good enough','the design’s most celebrated strength','a brief period of employment','Shortcoming means a fault or limitation.','meaning'),Q(1,'Which sentence identifies a shortcoming?','The app is useful, but its battery drains quickly.','The app meets every need and has no flaw.','The app is a short-term loan.','A limitation is explicitly named.','context'),Q(1,'Which collocation is natural?','address a shortcoming','address a shortfallly','come shortcoming of address','One can address or correct a shortcoming.','collocation'),Q(1,'The word suggests that something…','falls short of a desired standard','takes a shortcut through a park','is written in shorthand','The compound evokes falling short of what is wanted.','word-formation')]);
P('shortcut','Shortcut combines short and cut; it first referred to a quicker route and now also names a faster method that may omit steps.',[C('shortcut.s1','出行','We took a shortcut through the park to reach the station before the rain.','我们抄近路穿过公园，赶在下雨前到达车站。','take a shortcut through/across + place','名词，指比常规路线更快的路径。','route saves time.','出行')],M('They took a shortcut that added an hour and several kilometres to the usual journey.','They took a shortcut that saved time and distance on the usual journey.','绕远一小时不是更快的路径。','meaning'),[Q(1,'A shortcut through a park is…','a quicker route than the usual one','a path that is always longer','a list of shorthand symbols','The source sense is a faster path.','meaning'),Q(1,'Why take a shortcut before rain arrives?','It may help you reach the station sooner.','It guarantees a longer walk in the storm.','It repairs a shortcoming in a plan.','A shortcut saves time on a route.','context'),Q(1,'Which phrase is natural?','take a shortcut through the park','take a shortcut at the park throughly','do a shortcut the park to','Through identifies the route across the park.','grammar'),Q(1,'A figurative shortcut can be…','a quicker method that skips some usual steps','a path with no destination','a device that measures distance only','The word also applies to a faster method.','meaning')]);
P('shorten','Shorten is formed from short plus the verb-forming suffix -en; it means to make something shorter or become shorter.',[C('shorten.s1','服装','The tailor shortened the sleeves by two centimetres so the jacket would fit.','裁缝把袖子缩短了两厘米，让夹克更合身。','shorten something by + amount; shorten a sleeve','动词，表示使长度变短或使其本身变短。','tailor reduces length.','服装'),C('shorten.s2','写作','She shortened the report to four pages by removing repeated details.','她删去重复细节，把报告缩短到四页。','shorten a text/speech to + length','也表示删去内容，使文章或讲话篇幅变短。','editing cuts text.','写作')],M('The tailor shortened the sleeves by adding ten centimetres of extra fabric to each one.','The tailor shortened the sleeves by cutting away ten centimetres of fabric.','增加布料会加长袖子，而非缩短。','meaning'),[Q(1,'The tailor shortened the sleeves by two centimetres means…','made the sleeves two centimetres shorter','made the sleeves two centimetres longer','changed the jacket’s colour','Shorten sense 1 reduces length.','meaning'),Q(2,'How did the writer shorten the report?','By cutting repeated details from the text.','By increasing it to six pages.','By turning it into a verbal promise.','The second sense applies to editing text.','context'),Q(1,'Which construction is natural?','shorten the rope by one metre','shorten the rope with one metre longer','shortened the one metre rope by to','By gives the amount of reduction.','grammar'),Q(1,'The suffix -en in shorten helps form…','a verb meaning make or become short','a noun meaning a shortage','an adverb meaning soon','-en is used here to form a verb from an adjective.','word-formation')]);
P('shortfall','Shortfall combines short and fall, suggesting falling below what is required; it is the missing part of a required sum or an unmet target.',[C('shortfall.s1','财务','A shortfall in funding delayed construction until the council approved extra money.','资金缺口延误了施工，直到市议会批准追加款项。','a shortfall in funding; cover a shortfall','名词，指所需款项中尚未到位的部分。','funds below budget.','财务'),C('shortfall.s2','业绩','The team missed its sales target by twelve per cent, leaving a serious shortfall.','团队的销售额比目标低百分之十二，形成了明显差额。','a shortfall against/in a target; a sales shortfall','也指团队或公司未能达到的目标差额。','result below target.','业绩')],M('The charity covered its funding shortfall by receiving more money than its budget required.','The charity covered its funding shortfall by raising the amount it was missing.','超出预算的资金不是缺口。','meaning'),[Q(1,'A funding shortfall is…','money still missing from the amount needed','extra money beyond the approved budget','a loan that lasts a short time','Shortfall sense 1 concerns an unmet sum.','meaning'),Q(2,'A sales shortfall of twelve per cent means…','sales were below the target by that amount','sales exceeded the target by twelve per cent','the sales period lasted twelve months','Sense 2 compares performance with a target.','context'),Q(1,'Which phrase is natural?','cover a shortfall in funding','cover funding shortfallly','fall a short of funding','Cover a shortfall means supply what is missing.','collocation'),Q(2,'Which situation has a shortfall against a target?','A team sells 88 units after setting a goal of 100.','A team sells 120 units after setting a goal of 100.','A team has no sales goal.','The result is below its target.','meaning')]);
P('shorthand','Shorthand combines short and hand, originally referring to fast writing; it means a system of abbreviated signs or a concise substitute phrase.',[C('shorthand.s1','工作','The reporter used shorthand to record the interview quickly.','记者用速记法快速记录了采访内容。','take notes in shorthand; shorthand system','名词，指用特殊符号快速记录口语的系统。','reporter records speech.','工作'),C('shorthand.s2','语言','In the lab, “the blue team” became shorthand for the group responsible for field tests.','在实验室里，“蓝队”成了负责实地测试小组的简称。','shorthand for + phrase/idea; use X as shorthand','名词也指代替较长说明的简短名称或说法。','brief label replaces explanation.','语言')],M('The reporter took shorthand by writing every sentence out in full at normal speed.','The reporter took shorthand by using abbreviated signs to record speech quickly.','逐字完整书写不是速记符号系统。','distinction'),[Q(1,'A reporter taking shorthand is…','using special signs to write spoken words quickly','recording each word in full at a very slow pace','using a shortcut through the park','Shorthand sense 1 is a rapid writing system.','meaning'),Q(2,'If “blue team” is shorthand for the test group, it is…','a concise label replacing a longer explanation','a literal colour report only','a type of sewing method','The second sense names a brief substitute phrase.','context'),Q(1,'Which phrase is natural?','take notes in shorthand','take shorthandly notes in','shorthand to notes take of','In is used with the writing system.','grammar'),Q(2,'“GDP is shorthand for gross domestic product” illustrates…','a short phrase standing in for a longer name','a system of handwritten symbols','an unmet sales target','The abbreviation replaces the full term.','meaning')]);
P('shortly','Shortly is formed from short + -ly; it means soon, or in few words in a manner that may sound impatient.',[C('shortly.s1','时间','The train should arrive shortly, so please wait behind the yellow line.','火车很快就会到，请在黄线后等候。','arrive shortly; shortly after + event','副词，表示从现在起不久或某事之后很快。','arrival expected soon.','时间'),C('shortly.s2','交际','When asked for more detail, he replied shortly and ended the call.','被要求提供更多细节时，他简短而不耐烦地回答后挂断了电话。','reply/speak shortly; answer someone shortly','副词也表示话少而简短，常显得不耐烦或无礼。','terse answer ends call.','交际')],M('The train will arrive shortly, meaning passengers should expect it sometime next year.','The train will arrive shortly, meaning it is expected soon.','shortly表示不久，而不是一年以后。','meaning'),[Q(1,'If a train will arrive shortly, it will arrive…','soon','after several years','only if it is shortened','Shortly sense 1 means in a short time from now.','meaning'),Q(2,'A person who answers shortly may sound…','terse or impatient','warmly expansive','as if taking shorthand','The second sense can describe an abrupt brief reply.','context'),Q(1,'Which use of shortly is natural?','The meeting ended shortly after noon.','The meeting shortlyly ended in noon after.','The meeting ended shortness after noon.','Shortly after gives a short interval following noon.','grammar'),Q(2,'Which reply is most likely to be “shortly” in the terse sense?','“No. I already told you.”','“Let me explain all six reasons in detail.”','“The train arrives in five minutes.”','The first reply is brief and impatient.','meaning')]);
P('shortness','Shortness is formed from short + -ness; it names limited length, height, duration, supply, or a bodily condition such as difficulty breathing.',[C('shortness.s1','健康','The doctor asked whether the patient had experienced shortness of breath during exercise.','医生询问患者运动时是否出现过气短。','shortness of breath; shortness of time/supply','名词，指长度、时间或供应不足，也可指呼吸困难。','breathing symptom discussed.','健康')],M('She reported shortness of breath because breathing felt unusually easy and effortless.','She reported shortness of breath because she struggled to breathe during exercise.','呼吸毫不费力与气短症状相反。','meaning'),[Q(1,'Shortness of breath means…','difficulty breathing','a brief written message','a long pause between breaths by choice','The phrase names a breathing symptom.','meaning'),Q(1,'A doctor asking about shortness of breath is checking for…','a possible breathing problem','a fast route to the clinic','a shorthand writing system','The context is a medical symptom.','context'),Q(1,'Which phrase is standard?','shortness of breath','shortly of breathing','shortness for breathed','Shortness of breath is the established phrase.','collocation'),Q(1,'The suffix -ness in shortness turns short into…','a noun naming a state or quality','a verb meaning make short','a comparative adjective','-ness forms an abstract noun.','word-formation')]);
P('shortsighted','Shortsighted combines short and sighted; it literally describes limited distance vision and figuratively describes poor judgment about future effects.',[C('shortsighted.s1','决策','Cutting the maintenance budget was shortsighted because the repairs later cost twice as much.','削减维护预算的决定缺乏远见，因为之后维修费用翻了一倍。','a shortsighted decision/policy; be shortsighted to + verb','形容词，表示看不到长远后果、缺乏远见。','future costs ignored.','决策')],M('The council called the plan shortsighted because it carefully accounted for costs over the next thirty years.','The council called the plan shortsighted because it ignored foreseeable long-term costs.','充分考虑长期成本不是缺乏远见。','distinction'),[Q(1,'A shortsighted policy is one that…','ignores likely future consequences','is designed around long-term effects','uses a shortwave radio','The figurative sense concerns poor future judgment.','meaning'),Q(1,'Why was the budget cut shortsighted?','Later repair costs became much higher.','It prevented every future expense.','The budget was written in shorthand.','The decision ignored predictable later costs.','context'),Q(1,'Which phrase is natural?','a shortsighted decision','a shortly sighted decision','a short-sightedness decision','Shortsighted is the adjective modifying decision.','grammar'),Q(1,'The literal sense of shortsighted relates to…','difficulty seeing distant objects','difficulty hearing a shout','a shortage of close objects','The compound can refer to limited distance vision.','meaning')]);
P('shortwave','Shortwave is a compound of short and wave; in radio, it names transmissions using comparatively short wavelengths that can travel long distances via the ionosphere.',[C('shortwave.s1','通信','During the storm, the rescue team used a shortwave radio to contact a station hundreds of kilometres away.','暴风雨期间，救援队用短波无线电联系数百公里外的电台。','shortwave radio/broadcast; listen on shortwave','名词，指利用短波长无线电波进行的通信。','radio reaches distant station.','通信')],M('The rescue team called it shortwave radio because its very long wavelength could reach only the next room.','The rescue team used shortwave radio because its signals could reach a distant station.','短波常可经电离层反射进行远距离传播。','meaning'),[Q(1,'Shortwave radio is associated with…','radio wavelengths that can carry signals over long distances','sound that cannot leave the room','a short written note','The source sense concerns radio using short wavelengths.','meaning'),Q(1,'Why use shortwave during a storm?','It may reach a distant station when local links fail.','It guarantees that the antenna stops transmitting.','It shortens the rescue team’s names.','Long-distance communication is useful in emergencies.','context'),Q(1,'Which phrase is natural?','listen to a shortwave broadcast','listen to a shortwaveful broadcast','listen short-wave broadcastly','Shortwave modifies broadcast as a compound adjective/noun modifier.','grammar'),Q(1,'Shortwave refers to comparatively short…','radio wavelengths','written words','loan periods','The compound’s second element is wave.','word-formation')]);
P('shoshone','Shoshone is the English name of a Native American people and their language; the name is associated with the Shoshone self-designation, though its deeper etymology is uncertain.',[C('shoshone.s1','文化','The museum displayed a Shoshone-language map created with community advisers.','博物馆展出了一幅在社区顾问协助下制作的肖肖尼语地图。','Shoshone people/language; a Shoshone community','名词，指美国西部的肖肖尼人或其犹他-阿兹特克语系语言。','map labelled in language.','文化')],M('The label called the Shoshone language a Romance language descended from Latin.','The label identified Shoshone as a Uto-Aztecan language of the American West.','Shoshone属于犹他-阿兹特克语系，不是罗曼语族。','distinction'),[Q(1,'Shoshone may refer to…','a Native American people or the language they speak','a short-term loan','a kind of radio wavelength','The source entry includes both people and language.','meaning'),Q(1,'A Shoshone-language map is…','a map labelled in that language','a map written in Latin only','a map of radio frequencies','The compound identifies the language used.','context'),Q(1,'Which phrase is natural?','a Shoshone community','a Shoshone speakings community','a community Shoshone of the','Shoshone can modify the noun community.','grammar'),Q(1,'The deeper origin of the English name Shoshone is…','not certain from the available evidence','clearly a Latin word for a map','formed from short + -ness','The history should be stated cautiously.','word-formation')]);
P('shot','Shot is the past participle of Old English sceotan “to shoot”; as a noun it can mean gunfire, a sports attempt, a photograph or film take, an attempt, or an injected dose.',[C('shot.s1','安全','Residents reported a shot after hearing a single gun fired outside the station.','居民听到车站外有人开了一枪后报了警。','hear/fire a shot; a shot from a gun','名词，指开枪一次或某些枪发射的一组弹丸。','single gun report.','安全'),C('shot.s2','体育','Her final shot at goal went just inside the left post.','她最后一次射门恰好打进左侧门柱内。','take/attempt a shot at goal','名词，指把球踢、打或投向球门或目标的一次动作。','ball directed at goal.','体育'),C('shot.s3','摄影','The director repeated the final shot until the sunset light was right.','导演反复拍摄最后一个镜头，直到日落光线合适。','a close-up/wide shot; film a shot','名词，指照片或单个连续拍摄的镜头。','camera records scene.','摄影'),C('shot.s4','医疗','The nurse gave him a flu shot before the winter clinic closed.','冬季门诊结束前，护士给他打了一针流感疫苗。','get/give a shot; a shot of + medicine','名词也指一次尝试或针剂注射。','injection administered.','医疗')],M('The nurse gave him a flu shot by handing him a photograph of the vaccine box.','The nurse gave him a flu shot by injecting the vaccine.','此处shot指注射剂，不是疫苗包装照片。','meaning'),[Q(1,'A shot heard outside a station most likely refers to…','an act of firing a gun','a film photograph','a dose of medicine','Shot sense 1 includes gunfire.','meaning'),Q(2,'A shot at goal is…','an attempt to send the ball toward the goal','a camera frame from a film','an injection','The sports sense is an attempt directed at a goal.','context'),Q(3,'The final shot of a film is…','a continuous camera-recorded piece of film','the last bullet from a gun','a shortfall in funding','Shot sense 3 refers to a filmed take or sequence.','meaning'),Q(4,'A flu shot is…','a dose of vaccine given with a needle','a photograph of a clinic','a way of writing in shorthand','Shot sense 4 names an injection.','meaning')]);
P('should','Should developed as the past subjunctive form of Old English sceal “shall”; it expresses advice, duty, expectation, or a possible future event.',[C('should.s2','建议','You should call the clinic today if the fever continues.','如果发烧持续，你今天应该给诊所打电话。','should + base verb; should do something','情态动词，用来对明智做法提出建议。','advice under condition.','建议'),C('should.s3','预期','The parcel should arrive by noon according to the tracking update.','根据物流更新，包裹应该会在中午前送到。','should arrive/be + expected time','也表示某事按理可能或预计会发生。','tracking predicts arrival.','预期'),C('should.s1','义务','Visitors should keep their identification visible inside the secure area.','访客在安全区域内应把身份证件放在明显处。','should + base verb for duty','可表示某事是正确、被要求或有义务做的。','rule states expected conduct.','义务'),C('should.s4','可能','If you should need a quieter room, please ask the reception desk.','如果你需要更安静的房间，请向接待处提出。','if + subject + should + base verb','用于谈将来可能发生的情况，常见于if从句。','polite possible condition.','可能')],M('You should to call the clinic if the fever continues.','You should call the clinic if the fever continues.','情态动词should后接动词原形，不加to。','grammar'),[Q(2,'“You should call the clinic” most directly gives…','advice about a wise action','a description of a completed past event','a short written abbreviation','Should sense 2 offers advice.','meaning'),Q(3,'“The parcel should arrive by noon” expresses…','an expected or likely event','a strict prohibition','a photographed scene','Should can indicate expectation.','context'),Q(1,'Which sentence states an expected duty?','Visitors should keep their badges visible.','Visitors should to keep their badges visible.','Visitors keeping should their badges visible.','Should is followed by the base verb keep.','grammar'),Q(4,'“If you should need help, call me” refers to…','a possible future situation','a confirmed event in the past','a dose of medicine','Should can introduce a possible future event in an if-clause.','meaning')]);
P('should have','Should have is the modal construction should + have + past participle; it can express an unfulfilled past duty or a confident guess about what is completed by now.',[C('should have.s1','反思','We should have booked the tickets earlier, but the seats are sold out now.','我们本该早点订票，但现在座位已经售罄了。','should have + past participle; should have done something','表示过去本应做某事但实际没有做。','past opportunity missed.','反思'),C('should have.s2','推测','The parcel should have reached the depot by now, according to the tracking estimate.','按物流预计，包裹现在应该已经到分拣站了。','should have arrived/finished by now','也可推测某事到现在多半已经完成。','expected completed arrival.','推测')],M('We should have to booked the tickets earlier.','We should have booked the tickets earlier.','should have后接过去分词，不在have后加to。','grammar'),[Q(1,'“We should have booked earlier” implies…','booking earlier was advisable but did not happen','the booking is definitely still in the future','the seats were photographed','Should have + participle can express an unfulfilled past duty.','meaning'),Q(2,'“The parcel should have arrived by now” is…','a likely guess that it has arrived','a claim that it must arrive next year','a regret that no parcel was sent','Sense 2 makes a confident expectation about completion.','context'),Q(1,'Choose the correct form.','She should have called yesterday.','She should have to called yesterday.','She should has called yesterday.','The construction is should have + past participle.','grammar'),Q(2,'Which sentence uses should have for a present guess?','The repair should have finished by now.','I should have repaired it last week, but I forgot.','We should to repair it now.','The first predicts a completed result by now.','meaning')]);
P('shoulder','From Old English sculdor, a Germanic word; shoulder names the body joint/area, a roadside strip or hillside slope, and the act of accepting a burden.',[C('shoulder.s1','身体','She rested the heavy bag on her shoulder while unlocking the door.','她把沉重的包放在肩上，一边开门。','on one’s shoulder; shoulder pain','名词，指脖子与上臂之间的身体部位。','bag rests on body part.','身体'),C('shoulder.s2','交通','The driver pulled onto the hard shoulder when the warning light came on.','警示灯亮起后，司机把车停到了硬路肩上。','the hard shoulder; stop on the shoulder','名词也指道路旁供临时停车的窄带。','vehicle leaves traffic lane.','交通'),C('shoulder.s3','责任','The small team shouldered the cost of replacing the damaged equipment.','这个小团队承担了更换损坏设备的费用。','shoulder the cost/blame/responsibility','动词，表示承担困难的责任、费用或责备。','team accepts cost.','责任')],M('The driver stopped on the hard shoulder, the traffic lane in the middle of the motorway.','The driver stopped on the hard shoulder, the strip at the side of the road.','硬路肩在道路边，不是中间行车道。','distinction'),[Q(1,'A bag resting on someone’s shoulder is on…','the body area between neck and upper arm','the strip beside a motorway','the person’s elbow joint only','Shoulder sense 1 is a body part.','meaning'),Q(2,'A car on the hard shoulder is…','on the strip beside the road','in the centre of a traffic lane','on a hillside summit','Shoulder sense 2 names the roadside strip.','context'),Q(3,'The team shouldered the cost means the team…','accepted responsibility for paying it','placed it on a body joint','avoided every expense','The verb means take on a cost or burden.','meaning'),Q(1,'Which phrase is natural?','a bag on her shoulder','a bag at her shouldering','a shoulder of bag to','On identifies the body part supporting the bag.','grammar')]);
P('shout','Shout is a Middle English verb meaning to call loudly; its deeper origin is uncertain. It can name both the loud act of speaking and the call itself.',[C('shout.s1','交流','Please do not shout at the children; they can hear you from here.','请不要冲孩子们大喊；他们在这里能听见你。','shout at/to someone; shout for help','动词，指用很大声音说话或喊叫。','voice unnecessarily loud.','交流'),C('shout.s2','交流','A shout from the kitchen told us that dinner was ready.','厨房里传来一声喊叫，告诉我们晚饭准备好了。','a shout of + word/emotion; hear a shout','名词，指响亮的叫喊或呼喊声。','loud call carries message.','交流')],M('She shouted to her friend by whispering so softly that no one nearby could hear her.','She shouted to her friend by calling loudly across the street.','耳语很轻，不能算大声呼喊。','meaning'),[Q(1,'To shout across a street is to…','call in a very loud voice','write a short name for a long phrase','take a quick route','Shout as a verb means speak or call loudly.','meaning'),Q(2,'A shout from the kitchen is…','a loud call or cry','a quiet written note','a short-term contract','The noun sense names the sound.','context'),Q(1,'Which phrase is natural?','shout for help','shout helpfully to a under','shouting of help for to','For introduces what the person calls for.','grammar'),Q(1,'The deeper origin of shout is…','uncertain','certainly from Latin shoulder','formed from short + -age','The word’s earlier derivation is not firmly established.','word-formation')]);
P('shove','Shove comes from Old English scufan “push,” from a Germanic source; it means to push forcefully and roughly, or a strong rough push.',[C('shove.s1','动作','A passenger shoved the heavy door with both hands until it opened.','一名乘客用双手用力推沉重的门，直到门打开。','shove someone/something; shove at + object','动词，指用力且不太顾及分寸地推。','forceful push opens door.','动作'),C('shove.s2','动作','With one shove, the stuck cart rolled off the curb.','推了一下后，卡住的手推车滚下了路沿。','give something a shove; with a shove','名词，指一次有力而粗鲁的推。','single push moves cart.','动作')],M('He shoved the cart by leaving it untouched while it remained firmly against the wall.','He shoved the cart by pushing it away from the wall with force.','没有施力推车不符合shove的意思。','meaning'),[Q(1,'To shove a door is to…','push it forcefully and roughly','measure its width carefully','cover it with a shortwave radio','Shove sense 1 is a forceful push.','meaning'),Q(2,'One shove of the cart is…','one strong rough push','a long written explanation','a quick walk through a park','The noun names a push.','context'),Q(1,'Which phrase is natural?','shove the box under the table','shove under the box to tablely','shove the under table of box','Under the table states where the box is pushed.','grammar'),Q(1,'Which verb is closest in meaning to shove?','push','whisper','shorten','Shove means push with force and little care.','meaning')]);
P('shovel','Shovel probably comes from Old English scofl, a spade-like tool, and is related to the Germanic family of words for digging; as a verb it means moving loose material with such a tool.',[C('shovel.s1','工具','He left the shovel beside the flower bed after turning over the soil.','翻过花坛的土后，他把铲子放在旁边。','a snow/garden shovel; handle of a shovel','名词，指带宽刃和长柄、用来搬动物料的工具。','tool rests after digging.','工具'),C('shovel.s2','劳动','The neighbours shovelled snow from the shared path before sunrise.','天亮前，邻居们把共用小路上的雪铲掉了。','shovel snow/soil; shovel something off/out','动词，指用铲子搬运泥土、雪等松散物料。','snow cleared by tool.','劳动')],M('They shovelled the snow from the path by using a broom to sew it into a coat.','They shovelled the snow from the path with a broad-bladed tool.','shovel指用铲子搬运松散物料，不是缝制衣物。','meaning'),[Q(1,'A shovel is…','a broad-bladed tool with a long handle','a system of rapid handwritten symbols','a roadside parking lane','Shovel sense 1 names the tool.','meaning'),Q(2,'The neighbours shovelled snow by…','moving it with a shovel','letting it melt indoors','writing it down in shorthand','The verb means move loose material using the tool.','context'),Q(1,'Which phrase is natural?','shovel snow off the path','shovelly snow path off','shovel to the snow path','Off the path describes where snow is removed from.','grammar'),Q(1,'Which item is most suited to shovelling snow?','a long-handled tool with a wide blade','a camera lens for a film shot','a shortwave antenna','The tool’s broad blade lifts loose material.','meaning')]);
P('show','Show is from Old English sceawian “look at, inspect, display,” a Germanic verb; it means let someone see, make something clear, present a performance, or create an appearance.',[C('show.s1','交流','Could you show me your ticket before you enter the platform?','进站台前可以给我看一下车票吗？','show someone something; show something to someone','动词，指让某人看见某物。','ticket made visible.','交流'),C('show.s2','分析','The figures show that the repair costs fell after the policy changed.','这些数字表明政策改变后维修费用下降了。','show that + clause; show how/why','动词也表示把事实表明清楚或示范做法。','data demonstrates result.','分析'),C('show.s3','娱乐','The evening show begins at eight, and the doors open half an hour earlier.','晚间演出八点开始，场馆提前半小时开门。','a live/television show; put on a show','名词，指表演、节目或公开展览。','scheduled performance.','娱乐'),C('show.s4','外观','The polished table gave a show of luxury, although it was cheaply made.','这张打磨光亮的桌子显得奢华，尽管它做工廉价。','make a show of; for show','名词也指一种外观或表面表现，有时并非真实。','appearance differs from reality.','外观')],M('The figures show a decrease by hiding the data and giving no evidence of any change.','The figures show a decrease by providing data that clearly demonstrate the lower costs.','show在此表示证据表明事实，隐瞒数据不能证明下降。','meaning'),[Q(1,'“Show me your ticket” asks you to…','let the speaker see your ticket','explain a future possibility','move a cart with force','Show sense 1 means let someone see something.','meaning'),Q(2,'If figures show costs fell, they…','make that fact clear','put on a stage performance','give a merely false appearance','The second verb sense includes demonstrating a fact.','context'),Q(3,'An evening show at eight is…','a performance or programme','a shortage of seats','a handwritten abbreviation','Show sense 3 is an entertainment event.','meaning'),Q(4,'A polished table that gives a show of luxury has…','an appearance of luxury that may not be real','a factual display of its price','a true shortage of polish','This phrase uses show as an outward appearance.','meaning')]);
P('show off','Show off combines show with off; as a phrasal verb it can mean behave to attract admiration or perform impressive tricks to gain attention.',[C('show off.s1','社交','He showed off his restored bicycle to every neighbour who came by.','每个路过的邻居，他都要炫耀一番自己修复的自行车。','show off something; show something off to someone','动词短语，指故意表现自己或展示物品以博得赞赏。','seeks admiration.','社交'),C('show off.s2','表演','The skater showed off with a difficult spin before the judges began scoring.','评委开始打分前，滑冰运动员表演了一个高难度旋转。','show off with + trick/skill','也指为吸引注意而表演花式动作或高难技巧。','trick performed for attention.','表演')],M('He showed off his new bicycle by hiding it in the shed and refusing to let anyone see it.','He showed off his new bicycle by displaying it proudly to his neighbours.','藏起来不让别人看与show off的炫耀行为相反。','meaning'),[Q(1,'Someone who shows off a new car wants to…','make other people admire it or its owner','keep it completely hidden','describe how soon it will arrive','The first sense involves seeking admiration.','meaning'),Q(2,'A skater shows off with a difficult spin to…','draw attention through a skillful move','avoid performing any movement','write a note in shorthand','Sense 2 is about performing tricks for attention.','context'),Q(1,'Which phrase is natural?','show off a restored bicycle','show offing to a bicycle','show a bicycle offly','Show off can take the displayed object.','grammar'),Q(1,'In “He always shows off,” the criticism is that he…','tries to attract admiration','quietly accepts responsibility','walks with shortness of breath','The phrase often implies boastful attention-seeking.','usage')]);
P('showcase','Showcase combines show and case, originally a display case; it can name a glass display box, an event that presents something well, or the act of highlighting strengths.',[C('showcase.s1','展览','The antique necklace was kept in a locked showcase near the gallery entrance.','这条古董项链存放在展厅入口附近的上锁玻璃陈列柜里。','a glass/locked showcase; display something in a showcase','名词，指商店或博物馆陈列物品的玻璃柜。','object displayed behind glass.','展览'),C('showcase.s2','文化','The regional festival is a showcase for new films from independent directors.','这场地区电影节是展示独立导演新片的活动。','a showcase for + talent/product/art','名词也指突出展示某事物优点的活动或场所。','festival presents films.','文化'),C('showcase.s3','教育','The science fair showcased the students’ original experiments.','科学展展示了学生们独创的实验。','showcase someone’s work/strengths','动词，指呈现人或物，使其优点显而易见。','fair highlights work.','教育')],M('The museum placed the necklace in a showcase, an open cardboard box that hid it from visitors.','The museum placed the necklace in a showcase, a glass case that let visitors view it.','陈列柜用于展示物品，而非把它藏起来。','meaning'),[Q(1,'A museum showcase is usually…','a glass case used to display objects','a narrow strip beside a road','a short burst of rain','Showcase sense 1 is a display box.','meaning'),Q(2,'A festival is a showcase for new films when it…','presents those films to an audience','stores them out of sight','cuts them into small pieces','The event highlights the films.','context'),Q(3,'The science fair showcased student experiments means it…','presented them so their value was easy to see','made them shorter by removing steps','kept them in a drawer','The verb means display strengths or work.','meaning'),Q(1,'Which phrase is natural?','a showcase for emerging artists','a showcase to artists emergingly for','a show-cased of artist','For introduces what the event presents.','grammar')]);
P('shower','Shower is related to Old English scūr “shower of rain,” a Germanic word; it names a sprayed-water wash, a brief fall of rain or many small things, and the act of washing or giving abundantly.',[C('shower.s1','日常','She took a quick shower after cycling home in the heat.','她在炎热天气里骑车回家后快速冲了个澡。','take/have a shower; shower room','名词，指站在喷淋水下冲洗的方式或设备。','wash under sprayed water.','日常'),C('shower.s2','天气','A brief shower of rain crossed the valley, then the sun came out again.','一阵短暂的阵雨掠过山谷，随后太阳又出来了。','a shower of rain; passing shower','名词也指短时降雨，或大量小物一起落下。','short rainfall passes.','天气'),C('shower.s3','动作','Friends showered the newlyweds with handwritten cards and small gifts.','朋友们送给新婚夫妇许多手写卡片和小礼物。','shower someone with + praise/gifts','动词，指淋浴，或大量给予某人某物。','many gifts given.','动作')],M('The hikers took a shower by standing under a dry tap with no water flowing.','The hikers took a shower under sprayed water after the climb.','淋浴需要水流喷洒。','meaning'),[Q(1,'Taking a shower means…','washing under sprayed water','walking through a shortcut','writing in abbreviated signs','Shower sense 1 is a way to wash.','meaning'),Q(2,'A shower of rain is…','a brief period of rainfall','a glass cabinet for jewels','a missing amount of funding','Sense 2 includes a short fall of rain.','context'),Q(3,'Friends showered the couple with gifts means they…','gave them many gifts','washed them under a tap','cut their cards into strips','The verb can mean give abundantly.','meaning'),Q(1,'Which phrase is standard?','take a shower','take showerly','do a shower of rain at','Take a shower is the usual collocation.','collocation')]);
P('showery','Showery is formed from shower + -y; it describes weather that brings brief bursts of rain separated by brighter or dry periods.',[C('showery.s1','天气','The forecast is showery, so we packed raincoats but planned to walk between the clouds.','天气预报说会有阵雨，所以我们带了雨衣，也计划趁雨停时散步。','showery weather/day; a showery forecast','形容词，指间歇性下阵雨、其间有晴段的天气。','rain comes in bursts.','天气')],M('The afternoon was showery, with continuous heavy rain and no dry interval at all.','The afternoon was showery, with brief bursts of rain and dry intervals.','showery描述阵雨间有间歇，不是持续整日大雨。','distinction'),[Q(1,'Showery weather has…','short bursts of rain with brighter intervals','continuous rain with no break','no possibility of rain','That pattern is the source sense of showery.','meaning'),Q(1,'What should hikers expect on a showery day?','Passing showers separated by dry spells','A single permanent flood','A short-term shortage of sunlight only','Showers are intermittent.','context'),Q(1,'Which phrase is natural?','a showery afternoon','a showerily afternoon','an afternoon of showeryly','Showery is an adjective modifying afternoon.','grammar'),Q(1,'Showery is formed from the noun shower plus…','-y','-ness','-ment','The suffix -y forms the weather adjective.','word-formation')]);
P('showman','Showman combines show and man; it names an organizer of public entertainment or someone skilled at making events visually exciting.',[C('showman.s1','娱乐','The veteran showman kept the audience engaged with quick jokes between each act.','这位资深演出主持人在每个节目之间用机智笑话吸引观众。','a natural-born showman; a showman puts on + event','名词，指组织公众娱乐或擅长营造场面的表演型人物。','entertainer holds crowd.','娱乐')],M('The showman avoided all audiences and never organized or presented entertainment.','The showman organized the evening’s entertainment and kept the crowd interested.','不组织、不面对观众与showman的典型角色相反。','meaning'),[Q(1,'A showman is likely to…','organize entertainment or create a spectacle','repair a lift shaft','calculate a funding shortfall','The source sense describes an entertainment organizer or flair for spectacle.','meaning'),Q(1,'Why might a mayor be called a showman?','The mayor enjoys staging lively public events.','The mayor refuses to speak before any audience.','The mayor uses shorthand to write quickly.','A flair for spectacle fits the figurative sense.','context'),Q(1,'Which phrase is natural?','a seasoned showman','a showmanly of seasoned','a showman for seasonedly','Showman is a noun modified by seasoned.','grammar'),Q(1,'Showman is built from…','show + man','show + -ness','shower + -en','The compound joins show and man.','word-formation')]);
P('showy','Showy is formed from show + -y; it describes conspicuously bright or grand display, sometimes in poor taste, and plants with large eye-catching flowers.',[C('showy.s1','设计','The lobby’s showy gold curtains looked expensive but overwhelmed the small room.','大厅里华丽俗气的金色窗帘看似昂贵，却让小房间显得压抑。','showy clothes/decor; a showy display','形容词，指鲜艳华丽得可能令人觉得俗气。','decor is conspicuous.','设计'),C('showy.s2','植物','The gardener chose a showy variety of lily with large orange flowers.','园丁选了一种开着大朵橙花、格外醒目的百合。','showy flowers/plant; a showy variety','形容词也指植物开出惹眼的大花。','large bright blooms.','植物')],M('The garden had showy lilies, each producing no visible flowers and blending into the dark soil.','The garden had showy lilies with large bright flowers that caught the eye.','醒目的花卉应当显眼，而不是没有花、融入土中。','meaning'),[Q(1,'A showy gold curtain may be…','bright and grand, perhaps in a tasteless way','plain and nearly invisible','a piece of shortwave equipment','The first sense concerns conspicuous display.','meaning'),Q(2,'A showy lily is a plant with…','large bright flowers that catch attention','no flowers at all','a glass case around its leaves','This is the plant-specific sense.','context'),Q(1,'Which phrase is natural?','a showy decoration','a showily decoration','a showy of decoration','Showy is an adjective before a noun.','grammar'),Q(1,'The suffix -y in showy helps form…','an adjective meaning marked by or full of show','a noun for an amount missing','a verb meaning cut into strips','Showy is an adjective derived from show.','word-formation')]);
P('shred','Shred comes from Old English screade, “a piece cut off”; it is a small torn piece or tiny amount, and as a verb it means cut or tear into narrow pieces.',[C('shred.s1','数量','There was not a shred of evidence linking the neighbour to the broken window.','没有一丝证据能把邻居和破窗联系起来。','not a shred of + evidence/doubt','名词，指一小片，也可用于否定句表示极少量。','no evidence at all.','数量'),C('shred.s2','整理','Please shred the expired forms before placing them in the recycling bin.','请把过期表格碎纸后再放进回收箱。','shred paper/documents; shred something into pieces','动词，指切或撕成细小碎片。','documents cut finely.','整理')],M('The office shredded the old forms by binding them into complete, readable folders.','The office shredded the old forms by cutting them into small pieces.','整理成完整文件夹不是粉碎纸张。','meaning'),[Q(1,'“Not a shred of evidence” means…','not even a tiny amount of evidence','a large pile of reliable evidence','a film shot of the evidence','Shred sense 1 can mean a very small amount.','meaning'),Q(2,'To shred expired forms is to…','cut or tear them into small pieces','keep them intact for filing','show them in a glass case','The verb means reduce material to strips or fragments.','context'),Q(1,'Which phrase is natural?','shred the documents','shred at the documents into','a shreddedly document of','Shred takes a direct object.','grammar'),Q(1,'Which statement uses shred as a noun?','There is not a shred of doubt.','Please shred the letter.','The leaves shrivel in the heat.','A shred of doubt is a tiny amount.','meaning')]);
P('shrewd','Shrewd entered Middle English with an earlier negative sense related to wickedness; it developed the modern sense of sharp practical judgment, while its deeper origin remains uncertain.',[C('shrewd.s1','商业','A shrewd buyer compared repair records before making an offer on the car.','精明的买家在出价前比较了汽车维修记录。','a shrewd decision/investment; shrewd enough to + verb','形容词，指善于判断机会并采取实际有利行动。','buyer evaluates risk.','商业'),C('shrewd.s2','理解','Her shrewd question exposed the assumption that the report had left unstated.','她犀利的问题揭示了报告中没有明说的假设。','a shrewd observation/comment; shrewd about + issue','也指对实际情况理解敏锐。','question sees hidden assumption.','理解')],M('The shrewd buyer ignored the repair records and paid far above the car’s value without asking questions.','The shrewd buyer checked the repair records and negotiated a price that reflected the car’s condition.','忽略信息并付出远高于价值的价格不是精明判断。','distinction'),[Q(1,'A shrewd buyer is…','good at judging opportunities for practical advantage','unable to compare costs or risks','a person who shreds documents','Shrewd sense 1 concerns practical judgment.','meaning'),Q(2,'A shrewd question may…','reveal an unstated assumption','make a high-pitched unpleasant sound','describe a short burst of rain','The second sense is sharp understanding.','context'),Q(1,'Which phrase is natural?','a shrewd investment','a shortly investment','a shrewdness investment','Shrewd is an adjective modifying investment.','grammar'),Q(1,'The word’s earlier Middle English sense was…','negative, related to wickedness','a type of glass display cabinet','a brief rain shower','The modern positive practical sense developed from an older negative one.','word-formation')]);
P('shriek','Shriek entered English in Middle English; its deeper origin is uncertain. It names a sudden high cry, the act of crying sharply, or a sharp sound from a machine or alarm.',[C('shriek.s1','情绪','A shriek of surprise came from the room when the lights suddenly went out.','灯突然熄灭时，房间里传出一声惊叫。','a shriek of + fear/laughter/surprise','名词，指因恐惧、疼痛或激动发出的高声叫喊。','sudden human cry.','情绪'),C('shriek.s2','声音','The child shrieked when the cold water touched his feet.','冷水碰到孩子的脚时，他尖叫起来。','shriek with + emotion; shriek at + person','动词，指发出高而响的叫声或用尖厉声音说话。','child cries sharply.','声音'),C('shriek.s3','机械','The old engine gave a shriek as the train pulled away from the platform.','火车驶离站台时，老旧发动机发出刺耳的尖声。','a shriek from + alarm/engine','名词也指警报器或发动机的尖锐刺耳声。','machine emits high sound.','机械')],M('The engine gave a shriek, a low, gentle hum that was barely audible.','The engine gave a shriek, a loud sharp sound that made passengers cover their ears.','低沉轻柔的嗡鸣与刺耳尖声不同。','distinction'),[Q(1,'A shriek of surprise is…','a sudden high cry','a quiet written complaint','a shortfall in ticket sales','Shriek sense 1 is a high emotional cry.','meaning'),Q(2,'The child shrieked when cold water touched his feet means he…','cried out in a high voice','gave a silent shrug','shoveled snow','The verb refers to a loud high cry.','context'),Q(3,'An engine’s shriek is…','a loud sharp mechanical sound','a person’s shoulder movement','a long-term contract','The third sense includes machine or alarm sounds.','meaning'),Q(1,'Which phrase is natural?','a shriek of laughter','a shriek laughterly of','a laugh in shrewdness','Of introduces the emotion or event accompanying the cry.','grammar')]);
P('shrill','Shrill is a Middle English adjective for a sharp penetrating sound; its deeper Germanic history is uncertain. It describes a loud, high, unpleasant sound.',[C('shrill.s1','声音','A shrill whistle from the referee cut through the noise of the stadium.','裁判一声尖锐的哨响穿透了体育场的嘈杂声。','a shrill voice/whistle; sound shrill','形容词，指声音尖锐、响亮且刺耳。','high pitch stands out.','声音')],M('The referee blew a shrill whistle, a low and soothing tone that could barely be heard.','The referee blew a shrill whistle, a sharp high sound that was hard to ignore.','低柔、几乎听不见的声音不是shrill。','meaning'),[Q(1,'A shrill whistle is…','sharp, high, and unpleasantly loud','deep, quiet, and soothing','a display case made of glass','Those sound qualities define shrill.','meaning'),Q(1,'Why did the whistle cut through the stadium noise?','Its high sharp pitch was conspicuous.','It was too low to hear.','It was written in shorthand.','A shrill sound is penetrating and hard to ignore.','context'),Q(1,'Which phrase is natural?','a shrill voice','a shrillness voice','a shrill voicefully','Shrill is an adjective modifying voice.','grammar'),Q(1,'Which sound is most likely shrill?','A piercing high-pitched alarm','A soft low hum','A silent page turn','Shrill refers to sharp high sounds.','meaning')]);
P('shrimp','Shrimp is an old seafood name of uncertain deeper origin; it refers to a small edible sea creature and, informally and often rudely, a very small person.',[C('shrimp.s1','饮食','The restaurant served grilled shrimp with garlic and lemon.','餐厅供应蒜香柠檬烤虾。','grilled/fried shrimp; shrimp with + sauce','名词，指有薄壳、身体弯曲的小型可食海生动物。','seafood served.','饮食'),C('shrimp.s2','口语','The coach apologized after calling the new player a shrimp in front of the team.','教练当着全队的面叫新队员小矮子后道了歉。','a little shrimp; call someone a shrimp','非正式且常带冒犯，指身材特别矮小的人。','unkind nickname.','口语')],M('The menu listed shrimp, but described the dish as a large freshwater tree leaf.','The menu listed shrimp, a small edible sea animal served with garlic.','虾是海生动物，不是植物叶片。','distinction'),[Q(1,'Shrimp on a menu refers to…','a small edible sea creature','a short handwritten note','a plant with woody stems','The main sense is an edible sea animal.','meaning'),Q(2,'Calling someone a shrimp can be rude because it…','teases the person for being very small','praises their careful judgment','describes their radio equipment','The informal sense can be unkind.','context'),Q(1,'Which phrase is natural?','grilled shrimp with garlic','grilled shrimply to garlic','a shrimping of garlic grill','Shrimp can be served grilled with a sauce or seasoning.','collocation'),Q(2,'Which sentence uses shrimp figuratively?','The tall players teased him by calling him a shrimp.','We ordered shrimp for dinner.','The shrimp were served with lemon.','The nickname refers to a small person.','meaning')]);
P('shrine','Shrine came through Old English scrin from Latin scrinium “case or chest,” first associated with sacred objects; it names a place of worship or pilgrimage linked with a holy object, deity, or famous person.',[C('shrine.s1','宗教','Pilgrims left flowers beside the shrine built over the saint’s grave.','朝圣者把鲜花放在建于圣徒墓上的圣龛旁。','a shrine to/for + saint; visit a shrine','名词，指供奉圣物或圣徒陵墓的小型礼拜场所。','pilgrims visit sacred place.','宗教'),C('shrine.s2','宗教','Residents brought offerings to the small village shrine dedicated to a local spirit.','居民把供品带到供奉地方神灵的小村祠堂。','a shrine dedicated to + deity; village shrine','也指供奉神明或地方神祇的建筑或房间。','offerings at worship place.','宗教'),C('shrine.s3','文化','The old theatre became a shrine for film lovers who came to honour its history.','这座老剧院成了影迷凭吊电影历史的圣地。','a shrine to + person/idea; become a shrine for + admirers','还可指仰慕者专程前往的名人相关地点。','admirers visit cultural site.','文化')],M('Pilgrims visited the shrine to worship, but the building was merely an ordinary grocery store with no sacred or commemorative connection.','Pilgrims visited the shrine, a place of worship connected with a saint’s grave.','普通杂货店不符合宗教场所这一语境。','distinction'),[Q(1,'A shrine built over a saint’s grave is…','a small place of worship or a sacred structure','a glass box for shop merchandise','a roadside strip for cars','Shrine sense 1 includes a structure over a saint’s grave.','meaning'),Q(2,'A village shrine may be dedicated to…','a local spirit or deity','a sales target','a shortwave frequency','This is the place-of-worship sense.','context'),Q(3,'An old theatre can become a shrine for film lovers if…','admirers travel there to honour its history','it is converted into an ordinary warehouse','no one has any connection to it','Sense 3 covers a place connected with an admired figure or subject.','meaning'),Q(1,'Which phrase is natural?','a shrine to the local saint','a shrine by worshiply to sainted','a saint shrine of the to','To introduces the figure or idea honoured.','grammar')]);
P('shrink','Shrink comes from Middle English shrinken, a Germanic verb; it means become smaller in size, amount, or value, recoil from fear, or informally refer to a psychiatrist.',[C('shrink.s1','服装','The wool sweater shrank in the wash because the water was too hot.','羊毛衫因水温过高而在洗涤时缩水了。','shrink in the wash; shrink by + amount','动词，指尺寸、数量或价值变小。','fabric becomes smaller.','服装'),C('shrink.s2','态度','She does not shrink from difficult questions during the public hearing.','在公开听证会上，她并不回避棘手的问题。','shrink from + task/challenge','动词也指因害怕或厌恶而退缩、回避。','does not avoid challenge.','态度'),C('shrink.s3','口语','He made an appointment with a shrink after anxiety began affecting his sleep.','焦虑开始影响睡眠后，他预约了一位精神科医生。','see/visit a shrink','非正式名词，指精神科医生。','informal clinician appointment.','口语')],M('The sweater shrank in the wash, growing two sizes larger after the hot cycle.','The sweater shrank in the wash, becoming smaller after the hot cycle.','缩水会变小，不会变大。','meaning'),[Q(1,'A sweater that shrank in the wash…','became smaller','became longer and wider','was displayed in a showcase','Shrink sense 1 means decrease in size.','meaning'),Q(2,'She does not shrink from difficult questions means she…','does not avoid them out of fear','makes the questions physically smaller','answers them with a shower','Shrink from can mean recoil from or avoid a challenge.','context'),Q(3,'In informal speech, “a shrink” is…','a psychiatrist','a tailor who shortens sleeves','a glass display cabinet','Shrink has an informal noun sense for a psychiatrist.','meaning'),Q(1,'Which phrase is natural?','shrink by two centimetres','shrink to two centimetres longer','shrinkingly two centimetres of','By gives the amount of reduction.','grammar')]);
P('shrinkage','Shrinkage is formed from shrink + -age; it names a decrease in size, value, or number, or the amount lost.',[C('shrinkage.s1','制造','The tailor allowed for shrinkage when cutting the cotton because it might contract in hot water.','裁缝裁棉布时预留了缩水余量，因为棉布遇热水可能收缩。','allow for shrinkage; shrinkage of + material/value','名词，指尺寸、价值或数量减少的过程或减少量。','fabric loss anticipated.','制造')],M('The tailor allowed for shrinkage because the cotton was guaranteed to become larger after washing.','The tailor allowed for shrinkage because the cotton could become smaller after washing.','shrinkage指变小或减少，不是增大。','meaning'),[Q(1,'Shrinkage in fabric means…','a decrease in its size','a new display case for cloth','an increase in its length','Shrinkage names reduction.','meaning'),Q(1,'Why allow for shrinkage when cutting cotton?','It may contract during washing.','It will definitely turn into a showery forecast.','It has no measurable dimensions.','The tailor anticipates fabric becoming smaller.','context'),Q(1,'Which phrase is natural?','allow for shrinkage','allow shrinkingly for','a shrinkage to allowed of','Allow for means take the possible reduction into account.','grammar'),Q(1,'The suffix -age in shrinkage forms…','a noun for a process or amount','an adjective meaning full of shrink','a modal verb','-age helps form a noun naming the decrease.','word-formation')]);
P('shrivel','Shrivel is an English verb of uncertain deeper origin; it describes a plant or leaf drying and shrinking into wrinkles, or skin or cloth contracting into folds.',[C('shrivel.s1','植物','The leaves began to shrivel on the vine during the week-long heat wave.','持续一周的热浪中，藤上的叶子开始干枯萎缩。','leaves/fruit shrivel; shrivel up in heat','动词，指植物或叶片脱水、缩小并起皱。','heat dries leaves.','植物'),C('shrivel.s2','身体','His fingers shrivelled after a long soak in the cold bath.','他在冷水浴中泡了很久，手指起了皱。','skin/fingers shrivel; shrivel into folds','也指皮肤或布料收缩起褶。','skin contracts in water.','身体')],M('The heat made the leaves shrivel by keeping them fully hydrated and smooth.','The heat made the leaves shrivel by drying them until they became wrinkled.','充分水合且平滑与枯萎起皱相反。','meaning'),[Q(1,'Leaves that shrivel in heat…','dry, shrink, and become wrinkled','grow larger and stay crisp','become a glass display case','The plant sense describes drying and shrinking.','meaning'),Q(2,'After a long soak, fingers may shrivel by…','contracting into wrinkled folds','turning into a short-term loan','becoming a shrub','The second sense includes skin forming folds.','context'),Q(1,'Which phrase is natural?','the fruit shrivelled in the sun','the fruit shrivelled itself longer','the fruit was shrivelledly into','The verb can be used intransitively for fruit drying up.','grammar'),Q(1,'The deeper origin of shrivel is…','uncertain','definitely from the noun shrine','a clear combination of show + case','No specific older source is asserted.','word-formation')]);
P('shroud','Shroud is from Old English scrud “garment”; it names cloth used to wrap a body, a covering that hides something, or the act of covering completely.',[C('shroud.s1','葬礼','The family wrapped the body in a plain linen shroud before burial.','安葬前，家人用一块素色亚麻裹尸布包裹遗体。','a burial/linen shroud; wrap a body in a shroud','名词，指安葬时包裹遗体的一块布。','cloth covers body for burial.','葬礼'),C('shroud.s2','自然','A shroud of mist covered the valley before sunrise.','日出前，一层雾霭笼罩着山谷。','a shroud of mist/darkness; under a shroud','名词也指遮盖并隐藏下面事物的东西。','mist conceals valley.','自然'),C('shroud.s3','天气','Low cloud shrouded the mountain peak for most of the morning.','大半个上午，低云都笼罩着山顶。','shroud something in/with + covering','动词，表示把某物完全盖住，使其看不见。','cloud hides peak.','天气')],M('Low cloud shrouded the peak while leaving every part of it fully visible.','Low cloud shrouded the peak and hid it from view.','完全可见与被云遮住相矛盾。','meaning'),[Q(1,'A burial shroud is…','cloth used to wrap a body for burial','a tool for moving snow','a branch of a low woody plant','Shroud sense 1 names burial cloth.','meaning'),Q(2,'A shroud of mist over a valley is…','a covering layer that hides the view','a shower of small gifts','a clear sunny opening','Mist conceals what lies beneath.','context'),Q(3,'Cloud shrouded the mountain means the cloud…','covered it so it could not be seen','shortened it by a few metres','showed it to every visitor','Shroud as a verb means cover completely.','meaning'),Q(1,'Which phrase is natural?','a shroud of mist','a shroudly misted of','mist shroud to a','Of introduces the covering material or condition.','grammar')]);
P('shrub','Shrub is a Middle English word for a woody plant shorter than a tree that branches near the ground; its deeper origin is uncertain.',[C('shrub.s1','园艺','The gardener planted a flowering shrub beside the front steps.','园丁在前门台阶旁种了一株开花灌木。','a flowering/low shrub; plant a shrub','名词，指矮于树、近地面分枝的木本植物。','woody plant near steps.','园艺')],M('The gardener called the shrub a low woody plant, but it was a tall single-trunk pine tree.','The gardener planted a low woody plant that branched near the ground.','高大的单干松树不是灌木的典型形态。','distinction'),[Q(1,'A shrub is typically…','a low woody plant branching near the ground','a tall tree with one bare trunk','a short period of time','The source definition contrasts shrubs with taller trees.','meaning'),Q(1,'Where might a flowering shrub be planted?','beside the front steps in a garden','inside a sealed lift shaft','in a glass jewellery case','Shrubs are common garden plants.','context'),Q(1,'Which phrase is natural?','a flowering shrub','a shrubbed floweringly','a flower of shrubby to','Flowering modifies shrub as an adjective.','grammar'),Q(1,'What distinguishes many shrubs from trees?','They stay lower and branch near the ground.','They are always made of cloth.','They have no woody stems.','Low branching growth is part of the source sense.','meaning')]);
P('shrubby','Shrubby is formed from shrub + -y; it describes land full of low woody plants or a plant with that growth habit.',[C('shrubby.s1','地貌','The burned pines were replaced by a shrubby hillside covered in low woody growth.','被烧毁的松树被一片长满低矮木本植物的山坡取代。','a shrubby hillside/area; shrubby growth','形容词，指长满灌木或具有灌木生长习性的。','low woody plants cover slope.','地貌')],M('The hillside was shrubby, with no bushes or low woody plants anywhere on it.','The hillside was shrubby, with many low woody plants growing across it.','没有灌木植物就不能称为长满灌木的山坡。','meaning'),[Q(1,'A shrubby hillside is…','covered with low woody plants','covered only with deep water','a high-pitched sound','Shrubby describes land with shrubs.','meaning'),Q(1,'A shrubby plant has…','a low, branching growth habit','a smooth bare trunk like a tall tree only','a metal shaft','The adjective can describe a plant’s growth habit.','context'),Q(1,'Which phrase is natural?','shrubby vegetation on the slope','shrubbyly vegetation the slope on','vegetation shrub -y slope','Shrubby is an adjective modifying vegetation.','grammar'),Q(1,'Shrubby is formed from shrub plus…','-y','-less','-age','The suffix -y makes the adjective.','word-formation')]);
P('shrug','Shrug is a Middle English verb of uncertain deeper origin; it means raise and lower the shoulders to show doubt or indifference, or the shoulder movement itself.',[C('shrug.s1','交流','When asked who had moved the files, he shrugged and said he did not know.','被问到是谁移动了文件时，他耸耸肩，说自己不知道。','shrug one’s shoulders; shrug at + question','动词，指抬起再放下肩膀以示不确定、不知道或不在意。','gesture signals uncertainty.','交流'),C('shrug.s2','交流','She answered the question with a small shrug.','她耸了耸肩回答这个问题。','give a shrug; answer with a shrug','名词，指这种肩膀动作。','movement is response.','交流')],M('He shrugged to show certainty by keeping his shoulders completely still and nodding decisively.','He shrugged to show uncertainty by briefly raising and lowering his shoulders.','耸肩表示不确定或无所谓，静止并坚定点头表达相反。','meaning'),[Q(1,'To shrug often means…','raise and lower the shoulders to show uncertainty','make a loud high cry','cut paper into pieces','Shrug sense 1 is the shoulder gesture.','meaning'),Q(2,'She answered with a shrug means she answered with…','that shoulder movement','a long spoken explanation','a shortwave signal','The noun sense names the movement itself.','context'),Q(1,'Which phrase is natural?','shrug one’s shoulders','shrug one’s shoulderedly','shoulders shrug to a','The common expression is shrug one’s shoulders.','collocation'),Q(1,'A shrug may communicate…','“I do not know” or “I do not mind.”','“I am firing a gun.”','“The rain will be continuous.”','The gesture can signal doubt or lack of interest.','meaning')]);
P('shudder','Shudder is an old English verb of uncertain deeper origin; it names or describes a sudden bodily shake from fear, disgust, or cold, and a brief tremor in a machine or vehicle.',[C('shudder.s1','情绪','She gave a shudder when she imagined how close the car had come to the cliff edge.','想到汽车曾离悬崖边那么近，她不禁打了个寒战。','give a shudder; a shudder of fear/disgust','名词，指因恐惧、厌恶或寒冷而突然发抖。','body reacts to fear.','情绪'),C('shudder.s2','身体','He shuddered at the smell of the burnt rubber in the workshop.','他闻到车间里烧焦橡胶的气味时打了个寒战。','shudder at + sight/smell/thought','动词，指因恐惧、厌恶或寒冷突然颤抖。','disgust triggers reaction.','身体'),C('shudder.s3','机械','The engine gave a brief shudder before the bus stopped at the curb.','公交车停到路边前，发动机短促地抖了一下。','a shudder from/in + engine/vehicle','名词也指机器或车辆的一阵短促抖动。','engine vibrates.','机械')],M('The bus engine gave a shudder, running perfectly smoothly with no vibration at all.','The bus engine gave a shudder, vibrating briefly before the vehicle stopped.','完全平稳无振动与短促抖动相反。','distinction'),[Q(1,'A shudder of fear is…','a sudden shaking movement of the body','a long written note','a glass case in a museum','Shudder sense 1 is a bodily tremor.','meaning'),Q(2,'He shuddered at a burnt-rubber smell because…','disgust made him shake suddenly','he wanted to show off his car','he shortened the workshop','The verb sense includes a reaction to disgust.','context'),Q(3,'An engine shudder is…','a brief mechanical vibration','a plant with woody stems','a shower of rain','The third sense is a machine or vehicle tremor.','meaning'),Q(2,'Which phrase is natural?','shudder at the thought','shudder for a high pitched','a shudderingly thought at','At introduces the thing prompting the reaction.','grammar')]);
P('shuffle','Shuffle entered English in the sixteenth century; its deeper history is uncertain. It means walk with sliding steps or mix things into a different order, and it can name either action.',[C('shuffle.s1','动作','The dealer shuffled the cards before asking each player to take one.','发牌者洗了洗牌，然后让每位玩家抽一张。','shuffle cards; shuffle a deck','动词，指把东西重新混合排列。','cards mixed into new order.','动作'),C('shuffle.s2','动作','The tired traveller crossed the lobby with a slow shuffle.','疲惫的旅客拖着缓慢的步子穿过大厅。','walk with a shuffle; a slow shuffle','名词，指慢慢拖脚的走法或一次洗牌。','sliding walk.','动作')],M('The dealer shuffled the cards by placing them back in exactly the same order without mixing them.','The dealer shuffled the cards by mixing them into a new order.','不改变顺序就没有洗牌。','meaning'),[Q(1,'To shuffle cards is to…','mix them into a new order','keep them in precisely the same order','walk on a sidewalk','Shuffle sense 1 includes mixing things.','meaning'),Q(2,'A traveller with a slow shuffle is…','walking with sliding steps','running quickly toward the station','giving a loud cry','The noun sense can name a slow sliding walk.','context'),Q(1,'Which phrase is natural?','shuffle the deck before dealing','shuffle the deal before deckingly','a shuffledly deck the before','Shuffle takes the cards or deck as its direct object.','grammar'),Q(1,'Which use of shuffle is a noun?','He walked with a shuffle.','She shuffled the cards.','They shun waste.','The first sentence names the walking style.','meaning')]);
P('shun','Shun is from Old English scunian “avoid, shun”; it means deliberately keep away from a person or place, or deliberately avoid an action considered harmful or wrong.',[C('shun.s1','社交','After the dispute, she shunned the former colleague at every office event.','争执之后，她在每次公司活动中都刻意避开那位前同事。','shun a person/place; shun contact with + person','动词，指有意不接近某人或某处。','intentional social avoidance.','社交'),C('shun.s2','选择','He shuns unnecessary spending and saves part of each paycheck.','他避免不必要的开支，每次领工资都会存下一部分。','shun waste/excess/risk','动词也指有意不做自认为有害或不妥的事。','avoids waste.','选择')],M('After the dispute, she shunned her former colleague by inviting them to every event and seeking conversation.','After the dispute, she shunned her former colleague by keeping away from them at events.','主动接近和邀请不是刻意回避。','meaning'),[Q(1,'To shun a former colleague is to…','deliberately keep away from that person','invite that person to every meeting','ask that person for a shortcut','Shun means intentionally avoid.','meaning'),Q(2,'Someone who shuns unnecessary spending…','deliberately avoids wasteful purchases','buys every available luxury','shuts every shop permanently','The second sense applies to avoiding a harmful or unwanted action.','context'),Q(1,'Which phrase is natural?','shun unnecessary risk','shun for unnecessary risking','shunningly unnecessary risk','Shun takes the thing or action avoided as its object.','grammar'),Q(1,'Which verb is closest to shun?','avoid','display','shovel','Shun means deliberately keep away from.','meaning')]);
P('shut','Shut comes from Old English scyttan “shut, close”; as a verb it closes something or stops a business operating, and as an adjective it means not open.',[C('shut.s1','日常','Please shut the window before the rain reaches the desk.','雨水淋到桌子前，请把窗户关上。','shut a door/window/book; shut one’s eyes','动词，指把门、窗、书或眼睛移到关闭状态。','window moved closed.','日常'),C('shut.s2','商业','The factory shut for two weeks while its electrical system was replaced.','更换电气系统期间，工厂停产了两周。','shut a factory/business; shut down temporarily','动词也指让商店或企业暂时或永久停止运营。','business pauses operations.','商业'),C('shut.s3','日常','The window was shut, so no cold air came into the room.','窗户关着，所以冷空气没有进入房间。','be shut; keep something shut','形容词，表示未打开、关着的。','closed state.','日常')],M('Please shut the window by pushing it fully open so the rain can enter.','Please shut the window by moving it into its closed position.','推开窗户与关窗的动作相反。','meaning'),[Q(1,'To shut a window is to…','move it so that it is not open','make it wider','shred its glass','Shut sense 1 means close.','meaning'),Q(2,'The factory shut for two weeks means it…','stopped operating temporarily','opened a new office','was moved onto a hard shoulder','This sense applies to a business ceasing operations.','context'),Q(3,'If a window is shut, it is…','not open','fully raised and open','made of shortwave metal','The adjective means closed.','meaning'),Q(1,'Which construction is standard?','shut the door','shut to the door closed','shutly the dooring','Shut can take door as a direct object.','grammar')]);
P('shut out','Shut out combines shut and out; it means prevent someone or something entering, refuse to consider or accept someone or an idea, or keep an opposing team from scoring.',[C('shut out.s1','安全','The locked gate shut out the crowd while emergency workers cleared the building.','应急人员清理大楼时，上锁的大门挡住了人群。','shut someone out of + place; shut out the noise','动词短语，指阻止某人或某物进入。','gate prevents entry.','安全'),C('shut out.s2','心理','She tried to shut out thoughts of failure while preparing for the final exam.','准备期末考试时，她努力不去想失败的可能。','shut out thoughts/ideas; shut someone out','也指拒绝考虑某种想法或把某人排除在外。','deliberately avoids thoughts.','心理'),C('shut out.s3','体育','The goalkeeper shut out the visiting team for the third match in a row.','守门员连续第三场比赛让客队一分未得。','shut out an opponent/team','体育用法指使对方球队不得分。','opponent scores zero.','体育')],M('The goalkeeper shut out the visitors by allowing them to score five goals.','The goalkeeper shut out the visitors by preventing them from scoring.','对方进球与零封对手矛盾。','meaning'),[Q(1,'A locked gate shuts out the crowd when it…','prevents them from entering','invites everyone through','gives them a side dish','The first sense is to prevent entry.','meaning'),Q(2,'To shut out thoughts of failure is to…','deliberately refuse to think about them','write them in shorthand','display them in a showcase','The second sense concerns excluding thoughts or ideas.','context'),Q(3,'A team that is shut out in a match…','scores no points','wins by a large margin','moves its players to the sideline','In sport, shut out means hold a team scoreless.','meaning'),Q(1,'Which phrase is natural?','shut out the crowd','shut the crowd outly','shut out from the crowd of','The phrasal verb takes the excluded group as its object.','grammar')]);
P('shutdown','Shutdown combines shut and down; as a noun it means switching off a machine or system, or closing a business temporarily or permanently.',[C('shutdown.s1','技术','The computer requires a complete shutdown before the operating-system update begins.','开始操作系统更新前，电脑需要彻底关机。','a system/computer shutdown; initiate a shutdown','名词，指关闭机器、电脑或系统的操作。','device powers off.','技术'),C('shutdown.s2','商业','The factory announced a two-week shutdown to replace its damaged roof.','工厂宣布停产两周，以更换受损屋顶。','a temporary/permanent shutdown; announce a shutdown','名词也指工厂或企业暂时或永久停止运作。','business operations paused.','商业')],M('The computer completed a shutdown while remaining fully powered on and running every program.','The computer completed a shutdown by switching off its operating system and processes.','仍然正常运行不属于关机。','meaning'),[Q(1,'A computer shutdown is…','the act of switching off the machine or system','a method of showing off a new computer','a sudden shortage of electricity only','Shutdown sense 1 concerns switching a system off.','meaning'),Q(2,'A two-week factory shutdown means…','the factory stops operating for that period','the factory doubles its production','the factory moves onto a sidewalk','The second sense applies to a business closure.','context'),Q(1,'Which phrase is natural?','complete a system shutdown','complete shuttingly a system downage','complete a shutdown of system to','Shutdown is used as a countable noun here.','grammar'),Q(2,'What caused the shutdown in the example?','The roof needed replacement.','The computer needed a camera shutter.','The factory had a surplus of workers.','A temporary closure can allow repair work.','meaning')]);
P('shutter','Shutter may come from shut + -er, originally something that closes an opening; it names a window cover or a camera’s light-controlling part, and as a verb it means close a business permanently.',[C('shutter.s1','家居','They closed the wooden shutters before the storm arrived.','暴风雨来临前，他们关上了木制窗板。','open/close window shutters; wooden shutters','名词，指装在窗外、可以关上的木质或金属遮板。','covers window opening.','家居'),C('shutter.s2','摄影','Press the camera shutter halfway to focus before taking the photograph.','拍照前，先半按相机快门对焦。','press/release the shutter; shutter speed','名词也指相机曝光时开合的部件。','camera lets light in.','摄影'),C('shutter.s3','商业','The retailer shuttered its last downtown branch after years of falling sales.','多年销售下滑后，这家零售商关闭了市中心最后一家分店。','shutter a shop/store/business','动词，指彻底关闭店铺或企业。','store ceases permanently.','商业')],M('She pressed the camera shutter, the wooden panel mounted outside the bedroom window.','She pressed the camera shutter to let light reach the sensor and take the photo.','此处shutter指相机曝光部件，不是窗户遮板。','distinction'),[Q(1,'Window shutters are…','covers that close over a window','parts of a camera lens only','strips beside a road','Shutter sense 1 is a window cover.','meaning'),Q(2,'Pressing a camera shutter helps…','let light in for an exposure','block all light from a room','close a factory permanently','The camera sense concerns exposure.','context'),Q(3,'The retailer shuttered a branch means it…','closed the store','installed new window panels','shook the building','The verb sense means close a business.','meaning'),Q(1,'Which phrase is natural?','close the shutters before the storm','shutter the before storming close','a shutters closingly storm','Close is a normal verb with window shutters.','grammar')]);
P('shuttle','Shuttle is from Old English scytel “dart, arrow,” later used for the thread-carrying weaving tool; it also names a regularly travelling vehicle or spacecraft and the act of travelling repeatedly between places.',[C('shuttle.s1','交通','A shuttle bus runs every twenty minutes between the airport and the railway station.','机场和火车站之间每二十分钟有一班接驳巴士。','a shuttle bus/train; shuttle between two places','名词，指在两个相近地点间定期往返的交通工具。','regular transport links locations.','交通'),C('shuttle.s2','科技','The space shuttle returned safely after completing its research mission.','完成科研任务后，航天飞机安全返回。','space shuttle; loom shuttle','名词也可指可往返太空的航天器或织布机梭子。','spacecraft returns.','科技'),C('shuttle.s3','出行','The volunteers shuttled supplies between the shelter and the clinic all night.','志愿者整夜在避难所和诊所之间来回运送物资。','shuttle between + places; shuttle someone/something to + place','动词，指经常往返两地或运送人员、物品。','repeated transport.','出行')],M('A shuttle bus between the airport and station made only one trip and never returned between them.','A shuttle bus between the airport and station travelled regularly back and forth.','往返接驳车会在两地之间定期往返。','meaning'),[Q(1,'An airport shuttle bus…','travels regularly between nearby locations','is a one-way rocket','carries thread through a loom only','Shuttle sense 1 is regularly scheduled transport.','meaning'),Q(2,'A space shuttle is…','a spacecraft designed to travel to space and return','a wooden window cover','a shortfall in a target','The second sense includes a return-capable spacecraft.','context'),Q(3,'Volunteers shuttled supplies all night means they…','repeatedly carried them between places','stored them in one showcase','closed the clinic permanently','Shuttle as a verb describes repeated trips or transport.','meaning'),Q(1,'Which phrase is natural?','a shuttle between the hotel and airport','a shuttling to hotel at airportly','a shuttle of the hotel between to','Between identifies the two stops.','grammar')]);
P('shy','Shy is from Old English sceoh “timid”; it describes social nervousness, being slightly below a number, or suddenly moving aside or avoiding something.',[C('shy.s1','个性','The shy child stayed close to her parent when the visitors arrived.','客人到来时，害羞的孩子一直待在家长身边。','shy with/about + people; a shy person','形容词，指见人或被注意时紧张、不自在。','child hesitant with visitors.','个性'),C('shy.s2','数量','The fund is only two votes shy of the majority needed to pass the motion.','这项动议距离通过所需的多数票还差两票。','X shy of + number/target','形容词，也表示还差一点儿才达到某个数目。','count falls short by two.','数量'),C('shy.s3','动作','The horse shied away from the sudden flash of the camera.','马被相机突然闪光吓得猛然后退。','shy away from + person/thing/task','动词，指因害怕突然躲开或回避某事。','animal moves aside.','动作')],M('The fund was two votes shy of a majority, meaning it had already exceeded the majority by two votes.','The fund was two votes shy of a majority, meaning it still needed two more votes.','shy of表示尚未达到，不能表示已经超过。','meaning'),[Q(1,'A shy child may feel…','nervous or uncomfortable around unfamiliar people','eager to perform tricks for attention','certain to have enough votes','Shy sense 1 describes social discomfort.','meaning'),Q(2,'Two votes shy of a majority means…','two votes are still needed','the majority has been exceeded by two','the election has been cancelled','The phrase shows a small remaining shortfall.','context'),Q(3,'A horse that shies away from a flash…','moves suddenly aside in fear','stands still without reacting','takes a shower','The verb sense can mean recoil suddenly.','meaning'),Q(2,'Which sentence uses shy to describe a shortfall?','The proposal was one signature shy of approval.','The shy speaker avoided the crowd.','The horse shied at the noise.','One signature shy means one is still missing.','meaning')]);
P('shyness','Shyness is formed from shy + -ness; it names a tendency to feel awkward in company and hold back from speaking or participating.',[C('shyness.s1','教育','His shyness kept him from asking a question during the first week of class.','开学第一周，他因为害羞而没有提问。','shyness keeps/prevents someone from + -ing','名词，指在人前不自在、因而退缩的倾向。','hesitation in class.','教育')],M('Her shyness made her eager to address a packed room of strangers without any hesitation.','Her shyness made her hesitant to speak to a packed room of strangers.','毫不犹豫地面对陌生人发言与害羞退缩相反。','meaning'),[Q(1,'Shyness is…','a tendency to feel awkward and hold back in company','a sudden movement of an engine','a shortfall in funding','The source sense describes social hesitation.','meaning'),Q(1,'Why might shyness stop a student asking a question?','The student feels uncomfortable speaking before others.','The student is already a showman.','The student has too many votes.','Social discomfort can cause someone to hold back.','context'),Q(1,'Which phrase is natural?','shyness kept him from speaking','shyness kept him to speakingly','shyly kept him from shyness','Keep someone from + -ing expresses prevention.','grammar'),Q(1,'The suffix -ness turns shy into…','a noun naming a quality or tendency','a verb meaning make shy','a future modal','Shyness names the quality of being shy.','word-formation')]);
P('sibling','Sibling was formed in 1903 from Old English sibb “kinship” plus -ling; it names a person sharing the same parents and, by extension, a related unit at the same level.',[C('sibling.s1','家庭','Each sibling helped their younger brother prepare for the first day of school.','每个兄弟姐妹都帮助弟弟准备上学第一天。','a brother/sister/sibling; siblings in a family','名词，指与你同父同母的兄弟或姐妹。','family members share parents.','家庭'),C('sibling.s2','组织','The two sibling departments report to the same director but handle different tasks.','这两个同级关联部门向同一位主管汇报，但负责不同任务。','sibling unit/team/node; sibling departments','也指处于同一层级、彼此关联的单位之一。','peer units share manager.','组织')],M('The two departments were siblings because one reported to the other rather than sharing the same level.','The two departments were siblings because they were related units at the same organizational level.','上下级关系不符合此处“同级关联单位”的义项。','distinction'),[Q(1,'A sibling in a family is…','a person who shares the same parents','a parent’s employer','a distant stranger','Sibling sense 1 names a brother or sister.','meaning'),Q(2,'Sibling departments are…','related units at the same level','a department and its direct subordinate','a group of people who share a bedroom','The second sense concerns peer organizational units.','context'),Q(1,'Which phrase is natural?','her three siblings','her three siblingly','her siblings of three','Sibling is a count noun for brothers or sisters.','grammar'),Q(1,'Which word can replace sibling in a family context?','brother or sister','supervisor','shutter','The family sense refers to a brother or sister.','meaning')]);
P('sick','Sick is from Old English seoc, a Germanic adjective; it can mean ill, nauseated, bored or angry by something repeated, or refer collectively to ill people.',[C('sick.s1','健康','She stayed home because she was sick and had a fever.','她发烧生病了，所以待在家里。','be sick with + illness; feel sick','形容词，表示健康状况不好、患病。','fever and illness.','健康'),C('sick.s2','健康','The strong smell of paint made him feel sick during the renovation.','装修时，浓烈的油漆味让他感到恶心。','feel/be sick; make someone sick','形容词，表示感觉可能要呕吐。','smell causes nausea.','健康'),C('sick.s3','情绪','I am sick of waiting for a reply that never comes.','我对无休止地等回信感到厌烦了。','be sick of + noun/gerund','形容词，表示因某事持续太久而厌烦或恼火。','prolonged wait frustrates.','情绪'),C('sick.s4','医疗','The hospital provided beds and meals for the sick after the flood.','洪水过后，医院为病人提供床位和食物。','care for the sick; the sick','名词用法，指生病的人这一群体。','patients receive care.','医疗')],M('The smell made him feel sick, meaning he felt completely comfortable and had no nausea.','The smell made him feel sick, meaning he felt nauseated.','此处sick指恶心，而不是舒服。','meaning'),[Q(1,'A sick patient is…','not in good health','a person who feels no effects of illness','a brief rainfall','Sense 1 means ill.','meaning'),Q(2,'Paint fumes made him feel sick means…','they made him feel nauseated','they helped him recover','they made him take a short-term loan','The second sense is a feeling of wanting to vomit.','context'),Q(3,'“I am sick of waiting” means…','I am annoyed because waiting has continued too long','I have a fever caused by waiting','I am describing patients as a group','Sick of expresses frustration or boredom.','meaning'),Q(4,'“The sick” in a hospital report refers to…','people who are ill','the illness itself','the hospital equipment','The adjective can be used as a plural group noun.','grammar')]);
P('sicken','Sicken is formed from sick + -en; it means make someone feel likely to vomit or make someone feel strong aversion.',[C('sicken.s1','健康','The smell of spoiled fish sickened everyone waiting in the small room.','腐鱼的气味让等候室里的所有人都感到恶心。','sicken someone; be sickened by + smell','动词，指使某人产生想要呕吐的感觉。','odour causes nausea.','健康'),C('sicken.s2','情绪','Residents were sickened by the deliberate dumping of waste in the river.','居民对故意向河里倾倒垃圾的行为感到强烈反感。','be sickened by + action; sicken someone','也指使某人对某事产生强烈厌恶。','wrongdoing provokes aversion.','情绪')],M('The spoiled fish sickened the guests by making them feel hungry and eager to eat more.','The spoiled fish sickened the guests by making them feel nauseated.','腐坏气味通常使人恶心，而不是增加食欲。','meaning'),[Q(1,'A bad smell that sickens someone…','makes the person feel like vomiting','makes the person feel hungry','turns the smell into a shortwave signal','The first sense is physical nausea.','meaning'),Q(2,'Residents were sickened by illegal dumping means they…','felt strong aversion to the act','felt proud of the river pollution','were physically shortened','The second sense means disgusted by wrongdoing.','context'),Q(1,'Which construction is natural?','The smell sickened the visitors.','The smell sickened to the visitors.','The smell sickness the visitors.','Sicken is a transitive verb here.','grammar'),Q(1,'The suffix -en in sicken helps create…','a verb meaning make sick','a noun naming a person','an adverb meaning soon','Sicken means cause sickness or aversion.','word-formation')]);
P('sickle','Sickle comes through Old English sicol from Latin secula, related to secare “cut”; it is a hand tool with a curved blade for cutting crops.',[C('sickle.s1','农业','The farmer used a sickle to cut a small patch of wheat by hand.','农夫用镰刀手工收割了一小片小麦。','a curved-bladed sickle; cut crops with a sickle','名词，指带弯刃、用于割庄稼的手工具。','tool cuts grain.','农业')],M('The farmer harvested wheat with a sickle, a smooth wooden rake with no cutting edge.','The farmer harvested wheat with a sickle, a hand tool with a curved cutting blade.','没有刀刃的木耙不能割庄稼。','distinction'),[Q(1,'A sickle is used to…','cut crops by hand','display jewellery behind glass','close a camera shutter','Its curved blade cuts crops.','meaning'),Q(1,'Why might a farmer use a sickle on a small patch of wheat?','It is a hand tool for cutting crops.','It is a vehicle running between two stations.','It measures shortness of breath.','The tool is suitable for manual harvesting.','context'),Q(1,'Which phrase is natural?','cut wheat with a sickle','cut a sickling wheat by','a sickle for crop cutted','With introduces the tool used.','grammar'),Q(1,'The word’s Latin relative secare means…','cut','speak loudly','feel shy','The etymological family relates to cutting.','word-formation')]);
P('sickness','Sickness is formed from sick + -ness; it can name nausea or a disorder of the body or mind that affects how someone feels.',[C('sickness.s1','健康','The smell of the medicine caused a brief feeling of sickness.','药味引起了短暂的恶心感。','a feeling of sickness; morning sickness','名词，指想要呕吐的感觉。','medicine induces nausea.','健康'),C('sickness.s2','医疗','The clinic treated several kinds of sickness reported after the flood.','诊所治疗了洪水后报告的几种疾病。','a sickness; sickness caused by + condition','名词，也指影响身体或心理状态的病症。','clinic treats disorders.','医疗')],M('The medicine caused sickness, but the patient felt perfectly well and had no nausea or disorder.','The medicine caused sickness, making the patient nauseated.','完全无不适与出现恶心相矛盾。','meaning'),[Q(1,'A feeling of sickness can mean…','a feeling that one may vomit','a sudden high-pitched cry','a narrow strip beside a road','The first sense is nausea.','meaning'),Q(2,'A clinic treating sickness is treating…','a disorder affecting the body or mind','a short-term contract','a piece of shorthand','The second sense means illness or disorder.','context'),Q(1,'Which phrase is natural?','a feeling of sickness','a sickeningly of feel','sickness to a feelinged','Feeling of sickness is a standard noun phrase.','grammar'),Q(2,'Which sentence uses sickness to mean illness?','The flood clinic treated a rare sickness.','The smell gave him a brief sickness.','She felt sick of waiting.','The first refers to a disease or disorder.','meaning')]);
P('side','Side is from Old English side “side, flank,” a Germanic word; it names an edge or surface, a group or position, one aspect of a situation, or support for a group.',[C('side.s1','方位','Write your name on the side of the box, not on its lid.','把名字写在盒子的侧面，不要写在盖子上。','on the side of + object; left/right side','名词，指物体非正面、背面、顶面或底面的一个面或边。','label placed on edge surface.','方位'),C('side.s2','立场','Which side are you on in the debate about the new parking rules?','在新停车规定的辩论中，你支持哪一方？','take someone’s side; on one side of a dispute','名词，也指比赛、争论、战争或家族中的一方。','asks affiliation in debate.','立场'),C('side.s3','观点','There is a bright side to the delay: the team found a safer route.','这次延误也有好的一面：团队找到了一条更安全的路线。','a side of the issue; the bright side','名词，还可指情况的一个部分或看法。','positive aspect identified.','观点'),C('side.s4','立场','She sided with her brother when the two neighbours argued.','两位邻居争吵时，她站在哥哥那一边。','side with + person/group','动词，指在对立中支持某一方。','supports one party.','立场')],M('She sided with her brother by publicly supporting the neighbour who was arguing against him.','She sided with her brother by supporting his position in the argument.','支持对方而非哥哥，不符合side with的意思。','meaning'),[Q(1,'The side of a box is…','one of its surfaces or edges','the box’s contents only','a length of shortwave radio','Side sense 1 concerns a surface.','meaning'),Q(2,'Asking “Which side are you on?” asks…','which group or position you support','which surface of a box you labelled','whether you feel sick','Side sense 2 is a party in a dispute.','context'),Q(3,'The bright side of a delay is…','a positive aspect of the situation','the physical edge of a clock','the group that lost the debate','Side can mean one aspect or point of view.','meaning'),Q(4,'She sided with her brother means she…','supported him in the disagreement','stood on his shoulder','moved a step sideways','The verb means support one person or group.','grammar')]);
P('side dish','Side dish combines side and dish; it names a smaller serving eaten alongside the main part of a meal.',[C('side dish.s1','餐饮','The curry came with rice as a side dish rather than as the main course.','这份咖喱配米饭作为配菜，而不是主菜。','a side dish with + main course; serve as a side dish','名词，指随主菜一同上桌的少量食物。','rice accompanies curry.','餐饮'),C('side dish.s2','餐饮','She ordered a small dish of greens as a light side dish with the fish.','她点了一小份青菜，作为鱼肉旁的清淡配菜。','a small side dish; a side dish of + food','也指与较丰盛主菜搭配的清淡小份食物。','greens accompany heavier entrée.','餐饮')],M('Rice was served as a side dish, replacing the curry as the only main course.','Rice was served as a side dish alongside the curry.','配菜是与主菜同食的小份菜，不是取代主菜的唯一菜品。','distinction'),[Q(1,'A side dish is generally…','a smaller food portion served with the main meal','the only meal served at a table','a glass case for a menu','The first sense is food accompanying the main course.','meaning'),Q(2,'A small dish of greens beside fish is…','a light side dish','a shortfall in the meal','a type of sickness','This example fits the lighter accompanying portion.','context'),Q(1,'Which phrase is natural?','rice as a side dish','rice as a side dishingly','a side dish for rice as to','As a side dish describes its role in the meal.','grammar'),Q(1,'Which item is most likely a side dish?','a small serving of vegetables with a main course','the whole dinner replacing every other course','a camera shutter','Side dishes accompany a main dish.','meaning')]);
P('sidebar','Sidebar combines side and bar; in publishing or interface design, it is extra text or a panel placed beside the main page or screen.',[C('sidebar.s1','出版','A sidebar on the magazine page explained the science behind the main article.','杂志页面的侧栏解释了主文章背后的科学内容。','a sidebar on a page; sidebar panel','名词，指放在主文或屏幕一侧的补充文字或面板。','supplement appears beside main text.','出版')],M('The article’s sidebar replaced the main article and filled the entire page with no separate central text.','The article’s sidebar added a brief explanation beside the main text.','侧栏是主内容旁边的补充部分，不是取代主文。','distinction'),[Q(1,'A magazine sidebar usually contains…','extra text placed beside the main article','the entire issue’s main story only','a street-side walking path','Sidebar is supplementary material at the side.','meaning'),Q(1,'Why include a sidebar about scientific terms?','It can briefly explain material related to the main story.','It closes the magazine permanently.','It keeps readers from seeing the main story.','A sidebar supplements the central text.','context'),Q(1,'Which phrase is natural?','a sidebar on the page','a sidebarly page on the','a side of bar on page','On the page describes where the panel appears.','grammar'),Q(1,'In a website, a sidebar may be…','a panel beside the main screen content','the camera part that lets light in','a hand tool for cutting crops','The digital sense remains a side panel.','meaning')]);
P('sideline','Sideline combines side and line; it names work outside one’s main occupation or the boundary line along the side of a playing field.',[C('sideline.s1','职业','She teaches music as a sideline while working full-time as an accountant.','她全职做会计，同时把音乐教学作为副业。','a sideline to + main job; take up a sideline','名词，指主业以外的工作。','secondary paid work.','职业'),C('sideline.s1','体育','The coach stood near the sideline and signalled for a substitution.','教练站在边线附近，示意换人。','stand by/near the sideline; cross the sideline','名词，也指球场边界线。','boundary of field.','体育')],M('Music teaching was her sideline, meaning it was the full-time job that provided nearly all her income.','Music teaching was her sideline, a secondary job alongside her main accounting work.','sideline是主业之外的工作，不是主业本身。','meaning'),[Q(1,'A part-time sideline is…','work outside someone’s primary occupation','the person’s only full-time profession','a paved pedestrian path','The employment sense is secondary work.','meaning'),Q(1,'In a match, the coach standing by the sideline is…','near the boundary line of the pitch','on the centre of the field','inside a camera shutter','The sports sense is the edge line of the playing area.','context'),Q(1,'Which phrase is natural?','music teaching as a sideline','music teaching in a sideline jobly','a sideline of music teaches to','As a sideline marks a secondary role.','grammar'),Q(1,'A line marking the edge of a pitch is a…','sideline','side dish','shortfall','This is the second source sense.','meaning')]);
P('sidestep','Sidestep combines side and step; it means move quickly aside to dodge something or cleverly avoid a difficult question or duty.',[C('sidestep.s1','动作','He sidestepped the falling branch and moved safely onto the path.','他迅速向旁边一闪，躲开掉落的树枝，安全地走到小路上。','sidestep a person/object; sidestep quickly','动词，指迅速侧移以躲避某人或某物。','body dodges branch.','动作'),C('sidestep.s2','沟通','The minister sidestepped the question about repair costs and discussed the weather instead.','部长回避了有关维修费用的问题，转而谈起天气。','sidestep a question/duty; sidestep dealing with + issue','动词也指巧妙回避难答的问题或责任。','answer avoids issue.','沟通')],M('He sidestepped the falling branch by standing directly beneath it and refusing to move.','He sidestepped the falling branch by moving quickly to one side.','站在落枝下不动不是躲避动作。','meaning'),[Q(1,'To sidestep a falling branch is to…','move quickly to one side to avoid it','catch it with one hand','write a note in shorthand','The literal sense is a quick sideways dodge.','meaning'),Q(2,'A politician who sidesteps a question…','avoids dealing with it directly','answers it with precise figures','sets up a side dish','The figurative sense is evasion.','context'),Q(1,'Which phrase is natural?','sidestep a difficult question','sidestep to difficultly a question','step side question difficult','Sidestep takes the avoided object.','grammar'),Q(2,'Which action illustrates the figurative sense?','Changing the topic when asked about a missed deadline','Jumping aside from a falling branch','Walking along the sidewalk','The first evades a question or duty.','meaning')]);
P('sidewalk','Sidewalk combines side and walk; in American English it means the paved strip beside a street where pedestrians walk.',[C('sidewalk.s1','交通','Bicycles are not allowed on the sidewalk outside the crowded school entrance.','拥挤的学校入口外，人行道上不允许骑自行车。','walk on a sidewalk; paved sidewalk beside a street','名词，美式用语，指街道旁铺设的行人通道。','pedestrian path beside road.','交通')],M('The sign sent pedestrians onto the sidewalk, the fast-moving lane in the centre of the road.','The sign sent pedestrians onto the sidewalk, the paved path beside the street.','人行道在街边，供行人走，不是道路中央的车道。','distinction'),[Q(1,'A sidewalk is…','a paved strip beside a street for people to walk on','the centre lane for fast traffic','a short written abbreviation','That is the American English source sense.','meaning'),Q(1,'Why might bicycles be restricted on a crowded sidewalk?','Pedestrians use it as a walking path.','It is a shuttle route between airports.','It is a place for a camera shutter.','Sidewalks are primarily for pedestrians.','context'),Q(1,'Which phrase is natural?','walk along the sidewalk','walk sidewalkly along to','a walk on sideing','Along the sidewalk describes movement on the path.','grammar'),Q(1,'Sidewalk is used especially in…','American English','a Germanic modal construction','medical Latin','The source labels this as the American word.','word-formation')]);
P('sideways','Sideways is formed from side + way + the adverbial ending -s; it means moving or facing to the left or right, and as an adjective describes a side-facing position.',[C('sideways.s1','方向','He glanced sideways at the clock without turning his whole body.','他没有转动整个身体，只是侧眼看了看时钟。','look/glance sideways; move sideways','副词，指向左或右移动或朝向侧面，而非正前方。','eyes turn laterally.','方向'),C('sideways.s2','姿势','The delivery van was parked sideways across the narrow entrance.','送货车横着停在狭窄入口处。','park/turn something sideways; a sideways glance','形容词，指转成侧面朝前的状态。','vehicle oriented side-first.','姿势')],M('The van was parked sideways, with its front facing directly down the street and its side parallel to the curb.','The van was parked sideways, with its side facing the street across the entrance.','车头正向前、车身沿路停放并非横向停放。','distinction'),[Q(1,'He glanced sideways at the clock means he…','looked to one side','looked straight ahead without turning his eyes','closed his eyes in sickness','Sideways describes lateral direction.','meaning'),Q(2,'A van parked sideways across an entrance is…','turned so its side faces across the opening','parked straight along the curb','being used as a shuttle bus','The adjective sense describes side-facing orientation.','context'),Q(1,'Which phrase is natural?','move sideways through the doorway','move sideway throughly the door','move sidewise of door','Sideways is the usual adverb for this motion.','grammar'),Q(2,'Which use is adjectival?','a sideways glance','walk sideways','look sideways','The first phrase uses sideways before a noun.','grammar')]);
P('siege','Siege came through Old French siege “seat, sitting,” from Latin sedere “sit”; it names a military encirclement or, figuratively, a prolonged barrage of questions or demands.',[C('siege.s1','历史','The city remained under siege for months while the surrounding army waited for surrender.','军队包围着这座城市等待投降，它被围困了数月。','under siege; lay siege to + place','名词，指军队包围某处并等待其投降的行动。','army surrounds city.','历史'),C('siege.s2','媒体','The actor faced a siege of cameras and questions outside the courthouse.','演员在法院外被记者的镜头和问题团团围住。','a siege of + questions/cameras/requests','名词也指长时间面对不停的提问、批评或要求。','continuous attention surrounds person.','媒体')],M('The army laid siege to the city by leaving every road open and making no effort to surround it.','The army laid siege to the city by surrounding it and waiting for it to surrender.','不包围、不围困不构成军事围城。','meaning'),[Q(1,'A city under siege is…','surrounded by an army waiting for it to give up','hosting a short film show','recovering from a brief shower','Siege sense 1 is a military encirclement.','meaning'),Q(2,'A “siege of questions” is…','a prolonged barrage of questions','one polite question asked once','a physical wall around a city','The figurative sense describes nonstop demands or attention.','context'),Q(1,'Which phrase is standard?','lay siege to the city','lay a city siege on to','siege under lay the city','Lay siege to is the usual collocation.','grammar'),Q(1,'The Latin source sedere means…','sit','see','cut','The French ancestor meant sitting or a seat.','word-formation')]);
P('sierra','Sierra is borrowed from Spanish sierra “saw” and is used for a mountain range whose jagged line resembles saw teeth.',[C('sierra.s1','地理','A long sierra rose behind the desert town, its peaks forming a jagged skyline.','沙漠小镇后方耸起一条长山脉，峰顶连成锯齿状天际线。','a sierra; the Sierra + place name','名词，指峰线像锯齿一样起伏的山脉。','peaks resemble saw teeth.','地理')],M('The map labelled the sierra as a flat plain with no hills or peaks.','The map labelled the sierra as a mountain range with a jagged line of peaks.','平原没有锯齿状山峰。','distinction'),[Q(1,'A sierra is…','a mountain range with saw-toothed peaks','a midday nap','a sieve for flour','The source sense describes a jagged mountain range.','meaning'),Q(1,'Why might a map label a range “sierra”?','Its peaks form a serrated skyline.','The mountains are all underground.','It is a brief shower of rain.','The word evokes the teeth of a saw.','context'),Q(1,'Which phrase is natural?','a sierra rose behind the town','a sierra slept after lunch','a mountain sierra of sawed to','Sierra names the mountain range.','grammar'),Q(1,'The Spanish word sierra means…','saw','seat','signature','The mountain term is named for its saw-like outline.','word-formation')]);
P('siesta','Siesta is borrowed from Spanish siesta, from Latin sexta hora “the sixth hour,” referring to a midday rest.',[C('siesta.s1','生活','During the hottest months, the shop closes after lunch so staff can take a siesta.','最热的几个月里，商店午饭后关门，让员工午休。','take/have a siesta; afternoon siesta','名词，指午饭后的小睡或休息。','rest follows midday meal.','生活')],M('The shop announced a siesta, meaning staff would work continuously through lunch without resting.','The shop announced a siesta, meaning staff could rest after the midday meal.','siesta是午饭后的休息，不是取消休息继续工作。','meaning'),[Q(1,'A siesta is…','a rest or nap after the midday meal','a military blockade','a long-distance radio signal','The source defines siesta as a midday rest.','meaning'),Q(1,'Why might a shop close for a siesta in hot weather?','Staff can rest after lunch during the hottest hours.','Customers need to hear a loud alarm.','The shop is showing jewels in a case.','A siesta is an afternoon rest.','context'),Q(1,'Which phrase is natural?','take a siesta after lunch','take a siesta at the mountain range','siesta the naply after','Take a siesta is the normal construction.','collocation'),Q(1,'Siesta comes from a Latin phrase meaning…','the sixth hour','a saw-toothed mountain','to cut thin pieces','The Spanish word derives from sexta hora.','word-formation')]);
P('sieve','Sieve is from Old English sife, a Germanic word; it names a perforated kitchen tool that holds back solids while liquid passes, and the act of processing food through it.',[C('sieve.s1','烹饪','Press the berry pulp through a fine sieve to remove the seeds.','把浆果果肉压过细筛，去掉种子。','through a fine sieve; a kitchen sieve','名词，指让液体通过、留住固体的多孔工具。','seeds held back.','烹饪'),C('sieve.s2','烹饪','She sieved the flour into the bowl to remove small lumps.','她把面粉筛进碗里，去掉小结块。','sieve flour/sauce; sieve something into + container','动词，指把食物等过筛使之细腻。','flour passes through mesh.','烹饪')],M('She sieved the flour by pressing it through a solid sheet with no holes.','She sieved the flour through a mesh so the small lumps were left behind.','没有孔洞的板不能让面粉通过筛选。','meaning'),[Q(1,'A kitchen sieve is used to…','hold back solids while liquid passes through holes','close a window before a storm','shred paper into strips','That is the tool’s defining function.','meaning'),Q(2,'She sieved flour means she…','put it through a sieve to make it smooth','mixed it into a new card order','took a nap after lunch','The verb means process with the tool.','context'),Q(1,'Which phrase is natural?','press pulp through a fine sieve','press pulp through fine sievingly','sieve through to a pulp fine','Through identifies the tool the pulp passes through.','grammar'),Q(1,'Which example uses sieve as a verb?','Sieve the flour into the bowl.','The sieve has a fine mesh.','The bowl is on the table.','The first sentence uses sieve as an action.','meaning')]);
P('sift','Sift is from Old English siftan; it means shake powder through a sieve or examine information closely to separate what matters.',[C('sift.s1','烹饪','Sift the flour before adding milk so the batter has no lumps.','加牛奶前先筛面粉，让面糊没有结块。','sift flour/powder; sift something into + bowl','动词，指让面粉或其他粉末透过筛子。','powder passes through mesh.','烹饪'),C('sift.s2','研究','The investigators sifted through the old files for evidence about the missing funds.','调查人员仔细翻查旧档案，寻找资金失踪的证据。','sift through + evidence/files; sift information','动词也表示仔细检查信息，把重要内容筛选出来。','records searched for relevant facts.','研究')],M('The investigators sifted through the files by ignoring every document that might contain useful evidence.','The investigators sifted through the files carefully to find relevant evidence.','认真筛查信息不等于忽略所有相关文件。','meaning'),[Q(1,'To sift flour is to…','shake it through a sieve','press it into a solid cake immediately','cover it with a shroud','The first sense is physical sieving.','meaning'),Q(2,'Investigators sifted through old files means they…','examined them closely to find relevant information','threw all records away without reading them','put the files in a showcase','The figurative sense is careful information review.','context'),Q(1,'Which phrase is natural?','sift through the evidence','sift at evidence throughly to','sifted evidence through on','Through introduces the material being examined.','grammar'),Q(2,'Which sentence uses sift figuratively?','The editor sifted the submissions for original ideas.','Sift the flour into a bowl.','The sieve held back the seeds.','The editor is selecting relevant material.','meaning')]);
P('sigh','Sigh comes from Old English sican, a Germanic verb; it can mean let out a long audible breath that expresses a feeling or name the sound of that breath.',[C('sigh.s1','情绪','She sighed with relief when the final results showed that everyone was safe.','最终结果显示所有人都安全时，她如释重负地叹了口气。','sigh with relief/frustration; sigh at + news','动词，指发出表达情绪的长而慢的呼气。','relief expressed in breath.','情绪'),C('sigh.s2','情绪','A deep sigh came from the back row when the meeting ran late again.','会议再次拖延时，后排传来一声深深的叹息。','give/hear a sigh; a sigh of + feeling','名词，指这种呼吸声。','audible breath signals frustration.','情绪')],M('She sighed with relief by holding her breath silently and showing no reaction.','She sighed with relief by letting out a long audible breath.','无声屏息不是叹气。','meaning'),[Q(1,'To sigh with relief is to…','let out a long audible breath that shows a feeling','make a sharp high-pitched cry','walk with sliding steps','Sigh sense 1 is an expressive breath.','meaning'),Q(2,'A deep sigh from the back row is…','the sound of a long breath','a sudden machine shutdown','a written signature','The noun sense names the sound.','context'),Q(1,'Which phrase is natural?','sigh with relief','sigh reliefly with of','a sighed of relieved','With relief names the emotion accompanying the sigh.','grammar'),Q(1,'Which verb is closest to sigh?','exhale audibly','sift powder','shove roughly','A sigh is a long audible breath out.','meaning')]);
P('sight','Sight is from Old English gesiht, related to see; it means the ability or act of seeing, a visible thing or tourist attraction, and the act of spotting something.',[C('sight.s1','健康','The accident left her with poor sight in one eye, so she uses special lenses.','事故后她一只眼睛视力很差，因此使用特殊镜片。','lose/improve one’s sight; have good sight','名词，指看见事物的能力。','vision affected.','健康'),C('sight.s2','观察','We caught sight of a fox crossing the field just before dusk.','黄昏前，我们看见一只狐狸穿过田野。','catch sight of + person/thing; within sight','名词，指看见某物的行为或视野所及范围。','briefly sees fox.','观察'),C('sight.s3','旅行','The guide showed us the main sights of the old city on foot.','导游带我们步行参观了古城的主要名胜。','see the sights; a striking sight','名词，指看到的景象，复数常指旅游名胜。','tour visits landmarks.','旅行'),C('sight.s4','航海','The sailors sighted land shortly after sunrise.','日出后不久，水手们看到了陆地。','sight something; sight land','动词，指看见某物，尤其是突然发现或搜寻后发现。','lookout spots land.','航海')],M('The sailors sighted land by failing to see anything on the horizon.','The sailors sighted land when they spotted the coastline on the horizon.','看见陆地与未能看见相矛盾。','meaning'),[Q(1,'Poor sight in one eye means…','limited ability to see','a shortage of food','a missed appointment','Sight sense 1 concerns vision.','meaning'),Q(2,'We caught sight of a fox means…','we saw it, perhaps briefly','we gave it a signature','we shunned every animal','Catch sight of describes seeing something.','context'),Q(3,'The sights of a city are…','interesting places visitors go to see','the city’s only traffic signs','a series of loud cries','The plural sense commonly means tourist attractions.','meaning'),Q(4,'The sailors sighted land means they…','spotted it after looking','signed a contract for it','showered it with rain','Sight as a verb means see or spot.','grammar')]);
P('sightseeing','Sightseeing combines sight and seeing; it means visiting famous or interesting places while travelling.',[C('sightseeing.s1','旅游','We spent Saturday sightseeing in the old city and visited its museums and temples.','周六我们在古城观光，参观了博物馆和寺庙。','go sightseeing; sightseeing tour','名词，指旅行时参观著名或有趣的地方。','travellers visit landmarks.','旅游')],M('They went sightseeing by staying in the hotel room all day and visiting no places.','They went sightseeing by visiting the old city’s museums and landmarks.','整日不外出、不看景点不能算观光。','meaning'),[Q(1,'Sightseeing means…','visiting interesting places while travelling','staying home to read a map','signing a travel contract','The compound names tourist visits.','meaning'),Q(1,'A sightseeing tour of the old city might include…','museums, temples, and landmarks','a factory shutdown','a medical shot','Tourists visit places of interest.','context'),Q(1,'Which phrase is natural?','go sightseeing around the city','go sightseeingly to city around','sightseeing the go city','Go sightseeing is the standard phrase.','grammar'),Q(1,'Sightseeing combines…','sight + seeing','sick + ness','side + dish','The word joins seeing sights into one noun.','word-formation')]);
P('sightseer','Sightseer is formed from sightsee + -er; it names someone who visits famous or interesting places while travelling.',[C('sightseer.s1','旅游','Sightseers crowded the bridge at sunset to photograph the river and old towers.','日落时，观光客挤满桥面，拍摄河流和古塔。','a sightseer; sightseers visit + place','名词，指去观光名胜的人。','visitors photograph landmarks.','旅游')],M('The sightseer spent the entire trip at home and never visited any place of interest.','The sightseer visited the city’s landmarks and took photographs.','不参观景点的人不是观光游客。','meaning'),[Q(1,'A sightseer is…','someone who visits interesting places while travelling','a person who sells camera shutters','someone who avoids all travel','The noun names a tourist visitor.','meaning'),Q(1,'Why were sightseers on the bridge at sunset?','To view and photograph local landmarks','To attend a factory shutdown','To sift flour','They were sightseeing.','context'),Q(1,'Which phrase is natural?','a group of sightseers','a sightseeingly group of','a sightseer to groupings','Sightseer is a count noun for a visitor.','grammar'),Q(1,'The suffix -er in sightseer refers to…','a person who does the activity','the place where sights are kept','a past action','Sightseer means a person who goes sightseeing.','word-formation')]);
P('sign','Sign came through Old French signe from Latin signum “mark”; it can name an information board or mark, evidence of something, a written name, or communication by gesture.',[C('sign.s1','交通','A large sign warned drivers that the bridge was closed ahead.','一块大标牌提醒司机前方桥梁已关闭。','road/signpost sign; a sign says/shows + message','名词，指提供信息或警告的牌子、图画或记号。','board carries warning.','交通'),C('sign.s2','推断','Dark clouds are often a sign that rain will arrive soon.','乌云常常是即将下雨的迹象。','a sign of + condition; a sign that + clause','名词，也指表明某事存在、属实或将发生的现象。','clouds indicate rain.','推断'),C('sign.s3','文件','Please sign the form at the bottom and return it to reception.','请在表格底部签名，然后交回接待处。','sign a form/letter; sign one’s name','动词，指在文件上写下名字表示同意或作者身份。','name written on form.','文件'),C('sign.s4','手势','He signed to the driver to wait until the road was clear.','他打手势让司机等到道路畅通再走。','sign to someone to + verb; sign for + item','动词也指用手或头的动作传达信息。','gesture conveys instruction.','手势')],M('The sign warned drivers that the bridge was closed, but it was a dessert served with the meal.','The sign warned drivers that the bridge was closed; it was an information board.','此处sign是道路标牌，不是菜肴。','distinction'),[Q(1,'A warning sign beside a road is…','a board or mark giving information','a long breath expressing relief','a tourist visiting a landmark','Sign sense 1 includes an information board.','meaning'),Q(2,'Dark clouds as a sign of rain are…','evidence that rain may come','a written name on a form','a hand gesture to a driver','The second sense is evidence or indication.','context'),Q(3,'To sign a form is to…','write your name to show agreement or authorship','point at the form without writing','close the form as a business','Sign as a verb includes writing one’s name.','meaning'),Q(4,'He signed to the driver means he…','used a gesture to communicate','wrote his name on the vehicle','showed a tourist landmark','This is the gesture sense.','meaning')]);
P('sign up','Sign up combines sign with up; it means put one’s name down to participate in a course or service, or agree to a contract or official list.',[C('sign up.s1','教育','She signed up for an evening course in first aid at the community centre.','她报名参加了社区中心的急救晚间课程。','sign up for + course/activity','动词短语，指登记参加课程、活动或服务。','name entered for course.','教育'),C('sign up.s2','工作','The striker signed up with a new team after his previous contract ended.','前一份合同到期后，这名前锋与一支新球队签约。','sign up with + organization/team; sign up for a contract','也指同意合同或被列入正式名册。','contract agreed.','工作')],M('She signed up for the course by refusing to register and leaving her name off the list.','She signed up for the course by registering her name on the list.','不登记、名字不在名单上与报名相反。','meaning'),[Q(1,'She signed up for a first-aid course means she…','registered to take part','cancelled the course','gave the instructor a side dish','Sign up for an activity means register.','meaning'),Q(2,'A player signed up with a new team after a contract ended means…','the player agreed to join the team','the player avoided every agreement','the team put up a signboard','The second sense involves a contract or official listing.','context'),Q(1,'Which phrase is natural?','sign up for an evening class','sign up at an evening class forly','sign a class up for evening','For introduces the course or activity.','grammar'),Q(2,'Which sentence uses the contract sense?','The musician signed up with a new label.','I signed up for a pottery lesson.','She signed the form at reception.','Signing up with a label is an agreement to join it.','meaning')]);
P('signal','Signal comes from Latin signum “mark” through later Latin and French forms; it names a message-bearing sign, the act of sending or making one, and, formally, something especially important.',[C('signal.s1','交通','Wait for the green signal before crossing the railway line.','等绿灯信号亮起后再穿过铁路线。','a signal from + source; traffic signal','名词，指传递信息的声音、光、动作或电波。','light communicates permission.','交通'),C('signal.s2','驾驶','The driver signalled before turning left at the busy junction.','司机在繁忙路口左转前打了转向灯。','signal before turning; signal to someone to + verb','动词，指做动作或发信息，告知别人或显示可能情况。','driver communicates intention.','驾驶'),C('signal.s3','学术','The discovery was a signal achievement in the study of coastal erosion.','这项发现是海岸侵蚀研究中的一项重要成就。','a signal success/achievement','形容词，书面语，表示非常重要或显著。','achievement notable.','学术')],M('The driver signalled before turning by making no movement or sending any message to other road users.','The driver signalled before turning by switching on the indicator.','不发出动作或信息就没有打转向信号。','meaning'),[Q(1,'A green traffic signal is…','a light conveying a message or instruction','a signature on a contract','a piece of low woody vegetation','Signal sense 1 is a message-bearing cue.','meaning'),Q(2,'The driver signalled before turning by…','sending a message about the intended movement','shutting down the car','walking along the sidewalk','The verb sense communicates to other road users.','context'),Q(3,'A signal achievement is…','an especially important or noticeable achievement','a small unnoticed event','a literal electrical wire only','The formal adjective sense means notable.','meaning'),Q(1,'Which phrase is natural?','signal before turning','signal to turning beforely','a signaler before turn','The driver signals before carrying out the turn.','grammar')]);
P('signaler','Signaler is formed from signal + -er; it names a person whose job is sending and receiving signals, especially in military or railway settings.',[C('signaler.s1','交通','The signaler raised a red flag so the approaching train would stop safely.','信号员举起红旗，让驶近的火车安全停下。','a railway/military signaler; signaler sends a message','名词，指负责发送或接收信号的人。','worker transmits stop signal.','交通')],M('The signaler warned the train by hiding the flag and sending no visible or audible message.','The signaler warned the train by raising a clear stop flag.','不发送信号不能起到提醒作用。','meaning'),[Q(1,'A signaler is…','a person whose job is to send or receive signals','a person who signs a contract only','a person who takes a siesta','That is the source definition.','meaning'),Q(1,'Why did the signaler raise a red flag?','To communicate that the train should stop','To show off a new flag','To mark a side dish','The signal conveys an instruction to the train.','context'),Q(1,'Which phrase is natural?','the signaler flagged the train to stop','the signaler signalledly to a stopped train','the flagging signal of trainer','The signaler is the person sending the message.','grammar'),Q(1,'The suffix -er in signaler identifies…','a person who performs an action','a place where signals are stored','a past-tense form','-er forms an agent noun here.','word-formation')]);
P('signature','Signature came through French signature from Latin signare “mark”; it means a written name showing agreement or authorship, or a recognizable feature typical of someone or something.',[C('signature.s1','文件','The contract is not valid until both parties add their signature at the bottom.','双方都在合同底部签名后，合同才有效。','sign one’s signature; signature on a document','名词，指写在文件上表示同意的名字。','names authorize contract.','文件'),C('signature.s2','风格','Bright geometric patterns became the designer’s signature across the collection.','鲜明的几何图案成为这位设计师整个系列的标志性风格。','a signature style/feature; be the signature of + creator','名词也指某人、产品或风格的典型特征。','repeated feature identifies style.','风格')],M('The designer’s signature was a typical feature of the collection, but no one could recognize it because it never appeared in the designs.','Bright geometric patterns were the designer’s signature because they appeared throughout the collection.','从未出现的特征不能帮助识别某人的风格。','meaning'),[Q(1,'A signature at the bottom of a contract is…','a written name showing agreement','a glass case for the contract','a shortfall in the price','Signature sense 1 is a written name.','meaning'),Q(2,'Bright geometric patterns as a designer’s signature are…','a recognizable feature typical of the designer','a legally required handwritten name','a signal to stop a train','The second sense concerns a distinctive style feature.','context'),Q(1,'Which phrase is natural?','add your signature to the form','add signaturely your of form','a signature of adding at','A signature can be added to a document.','grammar'),Q(2,'Which item could be a chef’s signature?','a dish or flavour combination strongly associated with that chef','the chef’s legal name only','a warning sign on a road','A signature feature identifies a person’s work.','meaning')]);
P('signature dish','Signature dish combines signature and dish; it means a particular meal a restaurant or cook is especially well known for making.',[C('signature dish.s1','餐饮','The restaurant’s signature dish is slow-cooked lamb with herbs from the nearby hills.','这家餐厅的招牌菜是用附近山上的香草慢炖的羊肉。','a restaurant’s signature dish; famous for a signature dish','名词，指餐厅或厨师因做得出色而闻名的一道菜。','house specialty highlighted.','餐饮')],M('The menu called plain boiled rice the restaurant’s signature dish, although the restaurant was famous for its handmade dumplings.','The menu named the handmade dumplings as the restaurant’s signature dish.','招牌菜通常是餐厅最知名、最具代表性的菜。','meaning'),[Q(1,'A restaurant’s signature dish is…','a meal it is particularly famous for serving well','any dish never ordered by customers','a legal document signed by the cook','The word names a well-known house specialty.','meaning'),Q(1,'Why highlight the lamb as the signature dish?','It is a distinctive meal the restaurant is known for.','It is the only dish with a handwritten signature.','It is served as a sidewalk.','A signature dish represents the restaurant’s cooking.','context'),Q(1,'Which phrase is natural?','the chef’s signature dish','the chef signature dishly’s','a signed dish to chef','Possessive ’s identifies whose specialty it is.','grammar'),Q(1,'Which dish is most likely a signature dish?','The meal repeatedly praised as a cook’s specialty','A random item added yesterday and never served','A signboard beside a shop','Signature dish means a notable specialty.','meaning')]);
P('signboard','Signboard combines sign and board; it is a flat board bearing words or a picture and used as a sign.',[C('signboard.s1','商业','The inn’s wooden signboard creaked in the wind above the entrance.','客栈入口上方的木招牌在风中吱呀作响。','a wooden/shop signboard; put up a signboard','名词，指写有文字或图画、用作标志的平板。','board displays name.','商业')],M('The inn’s signboard was a flat board, but it carried no writing or picture and gave no indication of the business.','The inn’s signboard displayed the name and a small picture above the entrance.','用作标志的牌子应提供文字或图画信息。','meaning'),[Q(1,'A signboard is…','a flat board bearing writing or a picture as a sign','a camera part that controls light','a person who signs contracts','That is the source sense.','meaning'),Q(1,'An inn might hang a signboard to…','show its name or identify the business','shut out all visitors','record a shortwave broadcast','The board identifies the place.','context'),Q(1,'Which phrase is natural?','a wooden signboard above the door','a signboardly above wood dooring','a board sign to woodenly','The adjective wooden describes the board.','grammar'),Q(1,'Which object is a signboard?','A flat shop board with the shop’s name painted on it','A spoken sigh of relief','A curved crop-cutting tool','A signboard carries written or pictorial information.','meaning')]);
P('signer','Signer is formed from sign + -er; it names someone who writes a signature on an agreement or communicates using sign language.',[C('signer.s1','文件','Each signer received a copy of the agreement after adding their name.','每位签署人写下姓名后都拿到了一份协议副本。','a signer to/on an agreement; all signers','名词，指在协议上签名的人，也可指用手语交流者。','participants sign agreement.','文件')],M('Every signer received a contract, although none of them wrote a name or otherwise agreed to it.','Every signer received a contract after writing a name to show agreement.','没有签名或同意就不能按此义称为签署人。','meaning'),[Q(1,'A signer on an agreement is…','someone who writes a signature on it','someone who prints the signboard','someone who takes a siesta','Signer sense 1 is a person who signs.','meaning'),Q(1,'The signers received copies after…','adding their names to the agreement','shredding every copy','shutting the office','The signature records agreement.','context'),Q(1,'Which phrase is natural?','every signer received a copy','every signerly received copy of','a received signer of each','Signer is a count noun for a person.','grammar'),Q(1,'A signer may also be someone who…','communicates in sign language','sifts flour','shuttles a bus','The source includes a person who communicates in sign.','meaning')]);
P('significance','Significance comes from Latin significantia, from significare “indicate, signify”; it means importance, the meaning of a sign or action, or statistical evidence that a result is unlikely due to chance.',[C('significance.s1','研究','The team discussed the significance of the discovery for future treatment.','团队讨论了这项发现对未来治疗的重要性。','the significance of + finding/event; practical significance','名词，指某事对人或事态的重要程度。','researchers assess impact.','研究'),C('significance.s2','语言','The significance of the old symbol is still debated by historians.','历史学家仍在争论这个古老符号所表达的含义。','the significance of a word/symbol/action','名词也指词语、符号或行为所承载的意思。','symbol meaning debated.','语言'),C('significance.s3','统计','The trial result reached statistical significance at the five per cent level.','试验结果在百分之五的显著性水平上达到统计显著。','statistical/significance level; reach significance','统计学中指结果不太可能仅由偶然因素造成的程度。','statistical test result.','统计')],M('The result reached statistical significance, meaning the test showed it was very likely to be caused by chance alone.','The result reached statistical significance, meaning chance alone was an unlikely explanation under the test.','统计显著性表示结果不太可能仅由偶然造成。','meaning'),[Q(1,'The significance of a discovery is…','how much it matters or affects what happens','the spelling of the word discovery','the number of people who signed a form','Sense 1 concerns importance.','meaning'),Q(2,'The significance of an old symbol is…','the meaning it carries','its weight in grams','the number of tourists who saw it','Sense 2 is meaning conveyed by a sign.','context'),Q(3,'Statistical significance suggests that a result…','is unlikely to be explained by chance alone','is guaranteed to be important in daily life','was written on a signboard','The statistical sense is defined in terms of chance.','meaning'),Q(1,'Which phrase is natural?','the significance of the finding','the significantness to finding of','a significance findingly','Of identifies the finding whose importance is assessed.','grammar')]);
P('significant','Significant comes from Latin significant-, the present participle stem of significare “indicate, signify”; it means important or noticeable, meaningful, or statistically unlikely to be due to chance.',[C('significant.s1','经济','There was a significant rise in prices after the supply route closed.','供应路线关闭后，价格大幅上涨。','a significant rise/change/difference','形容词，表示大到足以产生影响或被注意到。','price rise is notable.','经济'),C('significant.s2','交流','She gave him a significant look when the meeting turned to the missing funds.','会议谈到失踪资金时，她意味深长地看了他一眼。','a significant look/silence; significant to + person','形容词，也可表示某事含有重要但不明显的意思。','look conveys implied meaning.','交流'),C('significant.s3','统计','The researchers found a statistically significant difference between the two groups.','研究人员发现两组之间存在统计学显著差异。','statistically significant; significant at + level','统计学中表示结果不太可能仅由偶然造成。','test rejects chance-only explanation.','统计')],M('The difference was statistically significant, meaning the researchers concluded it was likely just random noise.','The difference was statistically significant, meaning it was unlikely to be explained by chance alone.','统计显著结果不太可能只是偶然波动。','meaning'),[Q(1,'A significant rise in prices is…','large or important enough to be noticed','too small to detect','a brief period of low prices','The first sense is noticeable or consequential.','meaning'),Q(2,'A significant look may…','carry an important meaning that is not stated directly','measure a person’s eyesight','show the way to a sidewalk','This sense concerns implied meaning.','context'),Q(3,'A statistically significant result is…','unlikely to be caused only by chance','guaranteed to matter morally','always the largest result in the study','The statistical sense is about chance, not necessarily practical importance.','meaning'),Q(1,'Which phrase is standard?','a significant difference between groups','a significance differenceful between groups','a significantly difference','Significant is an adjective modifying difference.','grammar')]);
})();
